INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei', 'Shin Megami Tensei is a remaster of the original Super Famicom game with improved graphics and gameplay along with a new difficulty mode. The gameplay uses first-person navigation of dungeons and turn-based battles against demons. The player can recruit demons as allies by talking to them rather than fighting them, and two to three demons can be fused to create new demons.' FROM games WHERE igdb_id = 248790 ON CONFLICT (game_id, language_code) DO NOTHING;
