INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle of Shikigami', 'Castle of Shikigami is a dark, supernatural shoot-''em-up classic. Choose one of six characters and utilize their unique abilities to defeat the demons infesting modern-day Tokyo in this vertically scrolling shooting game. Use each character''s shot, special Shikigami attack and bomb to conquer each stage and it''s boss to ultimately discover who or what is behind "The Castle of Shikigami Incident".' FROM games WHERE igdb_id = 28519 ON CONFLICT (game_id, language_code) DO NOTHING;
