INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('card-games', 44957, '2001-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob36i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ovm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card Games', 'Card Games is a value-priced PlayStation title containing six different card games tied together with a casino interface. Draw Poker, Blackjack, Baccarat and Seven-card Stud are the traditional entries, with the less-familiar Speed and President rounding out the package. Casino mode starts you out with a small amount of chips and the goal of winning enough cash to purchase items at the shop. Merchandise includes new background music, access to higher stakes tables, and most importantly, furnishings for your room. When the game begins, your room is empty, but as you earn money you are able to buy a variety of products such as wallpaper, carpet and TVs. Your winnings and all merchandise purchased are saved on the memory card at the end of each session.' FROM games WHERE igdb_id = 44957 ON CONFLICT (game_id, language_code) DO NOTHING;
