INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-mario-world--3', 270346, '2001-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co779k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scoye5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario World', 'The remake of Super Mario World included in Super Mario Advance 2 for the Game Boy Advance. In this refreshed version for the portable system, you can choose to play as either Mario or Luigi in single player. If you''ve played the original, you''ll find that Mario controls much the same as the Super Nintendo counterpart, but his brother Luigi can jump a bit higher and float a short while, and Luigi''s fireballs will bounce higher as well. Saving in this game is available at any point during game, either on the overworld or inside of a level.' FROM games WHERE igdb_id = 270346 ON CONFLICT (game_id, language_code) DO NOTHING;
