INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Learning: Phonics Quest', 'Disney Learning: Phonics Quest challenges kids to enhance and master their phonics skills while taking a magical journey with Mickey and his friends. Using state-of-the-art voice recognition technology, kids will actually be able to speak their answers out loud as they master a variety of phonics-based, multilevel learning activities.' FROM games WHERE igdb_id = 59939 ON CONFLICT (game_id, language_code) DO NOTHING;
