INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lady Sia', 'Join Lady Sia, bold defender of a world invaded by a race of ruthless beastmen. Help her use her sword and her wits in an intense battle across land, sea and air to free her people. Acquire the magic of the elements to defeat the giant T''Soa bosses, and invoke Sia''s shapeshifting power in a final showdown against an unforgiving foe!' FROM games WHERE igdb_id = 6497 ON CONFLICT (game_id, language_code) DO NOTHING;
