INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alterego-browser-based-life-simulation-game', 16304, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kmpp2b5cyuogm2ehtoa6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jzsmmzjfxz1cfw9y4ffa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AlterEgo: Browser-Based Life Simulation Game', 'What if you could live your life over again? In Alter Ego, you can find out. In this text-based interactive fiction, you choose what happens next. It''s in the style of choose-a-path books, but with over a thousand multiple-choice questions, it''s much longer and deeper than traditional gamebooks. Alter Ego starts at birth and ends at death, including two substantially different versions, depending on whether you choose to be male or female. Will you grow up to be confident and happy? Will you fight with bullies, or befriend them? Will you find a date to the senior prom? Will you marry and have kids, or start your own business and become a millionaire? The choice is yours. If you enjoy interactive novels, you''ll love Alter Ego. This game will change your life. (official Text)  Developer''s Comment: "Alter Ego was originally written by Peter J. Favaro, Ph.D. It was published in 1986 for the Commodore 64, MS-DOS, Apple II, and Macintosh. The current edition of the Alter Ego game is a production of Choose Multiple LLC." (https://www.playalterego.com/credits.html)' FROM games WHERE igdb_id = 16304 ON CONFLICT (game_id, language_code) DO NOTHING;
