INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 72: The Beach Volley', 'A total of 26 characters from 8 countries appear in this game, which is fully-packed with combination play that is unique to beach volleyball. Different to volleyball, it is necessary to predict and calculate wind speed to determine whether you should attack or fake in. Realizing simple but in-depth controls, you can learn while you play in Training Mode.' FROM games WHERE igdb_id = 203068 ON CONFLICT (game_id, language_code) DO NOTHING;
