INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spec-ops-covert-assault', 9346, '2001-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gfw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spec Ops: Covert Assault', 'Spec Ops: Covert Assault is the third game in the budget-priced Spec Ops line for the PlayStation. The series takes the first-person shooter genre and attempts to fuse it with aspects of real combat, in the hopes of giving players a sense of what it is actually like to take on dangerous black ops military missions. Covert Assault is no different in this regard, as you''ll take on the role of two different elite rangers as they scour the globe, quietly ridding it of evil at every turn. In Covert Assault, you choose two rangers from a host of different soldiers with their own abilities. Select from the machine gunner, close-quarters fighter, sniper, grenadier, and rifleman. Once you''ve chosen your rangers, you will be able to customize them with a whole host of different guns and items such as body armor and grenades. You then enter into the game, which is made up of four different missions, ranging from the island of Sicily to the deep anonymous jungles of a far away place.' FROM games WHERE igdb_id = 9346 ON CONFLICT (game_id, language_code) DO NOTHING;
