INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Femme Fatale', 'Taisho era. Main character is a detective in Tokyo. He returns to hometown to dispose of his father''s legacy. Local policeman tells him about a case of girl death from illness at a boarding school, but under suspicious conditions. Detective decides to investigate the incident as he needs to stay at the town for some time anyway.' FROM games WHERE igdb_id = 125644 ON CONFLICT (game_id, language_code) DO NOTHING;
