INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hover Ace', 'Hover Ace is a futuristic arcade racer with guns. Player takes in control one of five types of hovercrafts (Bike, Scout, Sport, Police and military) and participate in events on different planets (Earth, Venus, Mars and Planet of Glaciers). After the events, he receives money award, which could be spent on new weapons, hovercrafts, items or used to upgrade already installed ones.' FROM games WHERE igdb_id = 54103 ON CONFLICT (game_id, language_code) DO NOTHING;
