INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mary-kate-and-ashley-winners-circle', 49966, '2001-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co81sj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7k7l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mary-Kate and Ashley: Winners Circle', 'MARY-KATE AND ASHLEY: Winners Circle for the Game Boy Color is a unique racing title that pits players against a plethora of obstacles while riding horseback. There are four different horses to choose from, each with a distinct look and style. Each horse has varying statistics for speed, jumping, and handling, requiring the player to make a careful choice to find the horse best-fitted to their racing style. Before riding you can also alter the clothing of the athlete to something of your choosing, then watch the changed sprite during gameplay. There are two modes of play: the first is a Training mode that lets you practice the controls and the course for the real competitions, and the second is the Steeplechase mode, where the real challenges lie. In this mode you must race through a course without being stopped by any of the many obstacles strewn about. MARY-KATE AND ASHLEY: Winners Circle is meant for young gamers, as the theme and graphics are sure to be loved by those looking for a light and exciting adventure.' FROM games WHERE igdb_id = 49966 ON CONFLICT (game_id, language_code) DO NOTHING;
