INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sakatsuku-tokudaigou-2-j-league-pro-soccer-club-wo-tsukurou', 392777, '2001-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobnin.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5gns.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SakaTsuku Tokudaigou 2: J. League Pro Soccer Club wo Tsukurou!', 'SakaTsuku Tokudaigou 2: J. League Pro Soccer Club o Tsukurou! is a sports management simulation game with RPG elements released for the Sega Dreamcast on December 13, 2001. It is part of the long-running SEGA "Let''s Make a Pro Soccer Club!" series (also known as "Pro Soccer Club o Tsukurō!" or simply "SakaTsuku"). It serves as a direct sequel to J.League Pro Soccer Club o Tsukurou! (1999) and SakaTsuku Tokudaigou (2000). The 2001 Dreamcast version of "SakaTsuku" delivered fully updated 2001 J.League experience. Both the real-world J.League clubs and the tournament structures reflect the 2001 season. All uniform designs have been accurately updated to match real-world kits. Thanks to the addition of Yokohama FC, J.League Division 2 now features 12 real-world clubs. Beyond the league, you''ll also have to manage your squad through the "J.League Cup," a home-and-away tournament, and the year-end "Winter Cup," a high-stakes single-elimination bracket. Depending on how deep your cup runs go, your team could play over 60 matches in a single year. Expect an intense and challenging campaign right from the opening whistle!' FROM games WHERE igdb_id = 392777 ON CONFLICT (game_id, language_code) DO NOTHING;
