INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golf Navigator Vol.3', 'The Golf Navigator game series let''s the player enjoy a golf simulation where the hallmarks are panoramic 360 degree views of the courses and an intuiative system which allows for proper impartation of power and english to the virtual golfer''s swing. The Vol.3 features 2 courses: Rope Club & Taiheiyo Sherwood. At the beginning of the game the player can choose between a male or a female caracter, select one of the courses and in each course he can play stroke play, free play or view the course data.' FROM games WHERE igdb_id = 203769 ON CONFLICT (game_id, language_code) DO NOTHING;
