INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('f1-world-grand-prix-2000', 45080, '2001-03-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa67t.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 World Grand Prix 2000', 'F1 World Grand Prix 2000 is a Formula 1 racing sim designed for true fans. Considerable attention has been devoted to realism and historical accuracy. The game features 22 real-life drivers from 11 F1 teams and the action takes place on detailed simulations of real tracks from around the world. The game features a Challenge Mode that puts the player in special situations based on actual race events that have occurred to F1 drivers. The challenge may be for the player to catch up to the leader with only a few laps to go, or to block out opponents and help a teammate pull ahead. The two-player mode in F1 World Grand Prix 2000 allows head-to-head racing against a friend on a vertical or horizontal split screen.' FROM games WHERE igdb_id = 45080 ON CONFLICT (game_id, language_code) DO NOTHING;
