INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('original-war--1', 9538, '2001-06-15', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20k6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqv4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Original War', 'An American geological expedition, under a UN mandate, assesses the natural resources in a distant part of Siberia, deep in the trackless steppes of Eastern Russia. But instead of oil, they discover a deposit of a hitherto unknown mineral. American scientists working for Department of Defense find out that this mineral is in fact identical to the substance used to power an extraterrestrial artifact in their possession. This object is called the EON (Extraterrestrial Object Nexus). It was found in 1919 by Colonel Emerson near the site of the Tunguska explosion. Emerson was the commander of a US military unit in charge of transporting US war supplies from the city of Vladivostok to the Eastern front during World War I. DoD Experiments have shown that items placed in the capsule are transported hundreds of thousands of years back in time. The American scientists were not able to understand its construction, nor could they manage to synthesize its fuel. Eventually, the machine - classified Top Secret - was stored, pending further advances in human science.' FROM games WHERE igdb_id = 9538 ON CONFLICT (game_id, language_code) DO NOTHING;
