INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kyoto-maiko-monogatari', 333558, '2001-06-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gmw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvjhr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyoto Maiko Monogatari', 'Kyoto Maiko Monogatari is a simulation game in which the player controls a young girl that begins her training to become a maiko, the game features music mini games (like copy the movements of the trainer in a drum), and different levels of training that only can be reached when the girl pass the previous ones. During the game there are video sequences to show different things about maiko way of life and the player can also interact with different trainers. The game features 2D graphics, first person perspective & japanese voice acting in the video sequences. Maiko is a Japanese word for ''dancing girl'' and is an apprentice geisha. A geisha is a traditional, female Japanese entertainer, whose skills include performing various Japanese arts, such as classical music and dance. It is the maiko, with her white make-up and elaborate kimono and hairstyle, that has become the stereotype of a "geisha" to westerners, rather than the true geisha. A woman entering the geisha community does not have to start out as a maiko, having the opportunity to begin her career as a full geisha. In fact, a woman above 21 is considered too old to be a maiko and becomes a full geisha upon her initiation into the geisha community. However, those who do go through the maiko stage enjoy more prestige later in their professional lives.' FROM games WHERE igdb_id = 333558 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 333558 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
