INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hunter II', 'Silent Hunter II is a World War II submarine simulation that puts players in command of German U-boats throughout various theaters of war. Players can engage in single missions or embark on a career-spanning campaign across seven maritime regions, from the Eastern United States to the Indian Ocean, facing both American and British naval forces. The game features 12 different U-boat types, historical accuracy in ranking against actual WWII submarine aces, and interoperability with its companion game Destroyer Command for online multiplayer warfare. After completing missions, players earn medals and commendations based on their performance and tonnage of enemy ships sunk.' FROM games WHERE igdb_id = 992 ON CONFLICT (game_id, language_code) DO NOTHING;
