INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StepMania', 'StepMania is a cross-platform rhythm video game and engine. It was originally developed as a simulator of Konami''s arcade game series Dance Dance Revolution, and has since evolved into an extensible rhythm game engine capable of supporting a variety of rhythm-based game types. It can be played with a variety of peripherals, most commonly dance mats or ''pads''. Several video game series, including In the Groove and Pump It Up Pro use StepMania as their game engine.' FROM games WHERE igdb_id = 51311 ON CONFLICT (game_id, language_code) DO NOTHING;
