INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boeboeks: De Tocht Naar Opa Kakadoris', 'Piepel, one of the children of the Boeboeks, very small creatures, becomes ill. Help his sister Soeza to get the miracle cure from Grandpa Kakadoris, a piece of the cotton candy web. Based on the story ''The Cotton Candy Web'' by Marc De Bel.' FROM games WHERE igdb_id = 334233 ON CONFLICT (game_id, language_code) DO NOTHING;
