INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Severance: Blade of Darkness', 'Severance: Blade of Darkness follows the fate of four characters and their quest to defeat an evil Necromancer and retrieve a legendary sword. The player can choose between the characters, who are a Knight, a Barbarian, A Dwarf and a Ranger/ Amazon type female character. All characters have different starting areas but eventually end up in the same levels. Yet, the sequence of the stages can be chosen as a world map in between the stages prompts you to decide where you want to go next, maybe look for help at the Dwarven Mines or go face the Orcs at their dwelling.' FROM games WHERE igdb_id = 5623 ON CONFLICT (game_id, language_code) DO NOTHING;
