INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doubutsu no Mori', 'Doubutsu no Mori is the name of the first installment in the Animal Crossing series. It was released only in Japan for the Nintendo 64. It was later remade for the GameCube in 2002, and released worldwide as Animal Crossing. This game is compatible with the Expansion Pak and is displayed in a higher resolution when it is used (640x480 as opposed to 320x240).' FROM games WHERE igdb_id = 44042 ON CONFLICT (game_id, language_code) DO NOTHING;
