INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s Pro Skater 3', 'Tony Hawk''s Pro Skater 3 is a 2001 skateboarding video game and the third installment in the Tony Hawk''s series. Skate as the legendary Tony Hawk or choose from a dream team of 12 top pro skaters, including old favorites like Lasek, Thomas, Muska, and Steamer, as well as new talent like Gilfberg, Caballero, Koston, and Mullen. Travel from L.A. to Tokyo, Suburbia to Skater''s Island performing challenges and meeting goals with new moves that include the Revert, which allows you to link vert tricks, and flatland tricks such as Caspers, the Primo, and Handstand Manual.' FROM games WHERE igdb_id = 914 ON CONFLICT (game_id, language_code) DO NOTHING;
