INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aidyn-chronicles-the-first-mage', 2850, '2001-03-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9n75.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h5kpgmjoy2puxfpxprhv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aidyn Chronicles: The First Mage', 'The king took him in at a very young age, but Alaron is now old enough to realize that he was adopted deciding to set out on a quest to track his own heritage. Along his journey, Alaron has had the fortune of meeting up with a party of others that are looking for adventure. You can choose to play as any of 13 characters. A more or less traditional role-playing game, AIDYN CHRONICLES: The First Mage is a brilliant mix of interaction, fighting, and extensive exploration. All of the battles take place in an innovative turn-based system, challenging you to handle both combat and real-time strategy. All of the characters and environments in the game are rendered in full 3D, and the characters have complete freedom in their ranges of movement. There''s more territory in the game''s expanses than you''ll ever get a chance to see, and the sheer diversity of the character types is really impressive. If you like role-playing games, you''ll want to check out this installment of Aidyn Chronicles.' FROM games WHERE igdb_id = 2850 ON CONFLICT (game_id, language_code) DO NOTHING;
