INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen Alpha for Dreamcast', 'Super Robot Taisen Alpha for Dreamcast is a strategy simlulation game for Dreamcast, released on 2001. The game is an extended port of Super Robot Taisen Alpha with changes in the system, including an overall 3D transition, more titles in the game, and the ability to use coalescing attacks.' FROM games WHERE igdb_id = 241829 ON CONFLICT (game_id, language_code) DO NOTHING;
