INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rescue-copter', 44977, '2001-12-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9j2c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4p06.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rescue Copter', 'The company behind the Jet Copter and Jet Stream series in Japan, AquaSystem, flies its Rescue Copter across the Pacific for this stateside PlayStation release. Players engage in fifteen missions consisting of border patrols, daring rescues, transport runs, crop dusting, treasure hunts, and fire fighting. Four types of helicopters, each geared for specific tasks, include the R-22 (training, crop dusting), AS350B3 (equipped with cables for external transporting), BK117 (rescue and transport), and the 47G4A-Soloy (low flying crop duster). Five practice modes allow players to ease into the controls by offering take-off and landing, hovering, flight, cargo, and fire fighting drills. Scores and medals (gold, silver, or bronze) are based on the amount of time it takes to complete a mission, and mission replay videos are available at the touch of a button. Other features include two difficulty settings, easy and expert (which factors damage and wind into the challenge), three camera angles, and a free flight mode using maps unlocked in successful missions.' FROM games WHERE igdb_id = 44977 ON CONFLICT (game_id, language_code) DO NOTHING;
