INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ballistics', 7495, '2001-11-06', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tkxtjn0engza8vy9nqgc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballistics', 'Ballistics is a futuristic racing computer game developed by Grin and published by Xicat Interactive in 2001. Grin developed an arcade version of the game, released in 2002 featuring a unique reclined seating position cabinet by Triotech Amusement. Players race across seven different tracks in various leagues against other competitors on high-speed hoverbikes. The game was Grin''s first to be released, and featured the first version of their Diesel game engine. Grin worked closely with NVIDIA to incorporate then new technologies into the game, and was marketed as one of the flagship titles for the GeForce 3 Series of graphics cards. Critical reaction was generally favourable, with reviewers being impressed by the beauty of the graphics and the thrilling depiction of speed. They were however, slightly disappointed with the shallow nature of the gameplay. A newer version of the arcade game was released in 2003, incorporating motion simulator technology into the arcade cabinet.' FROM games WHERE igdb_id = 7495 ON CONFLICT (game_id, language_code) DO NOTHING;
