INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('killer-tank', 47098, '2001-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/izsufskpravoea10upex.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Tank', 'An evil Russian Scientist dreams of world domination, and you absolutely do not play a square-jawed American, striving to defend democracy. It’s time to back the mad scientist for a change!  So, man the maniac’s super-tank and thunder through twenty all -action missions, spreading mayhem and carnage. Your tasks will range from seek-and-find missions to all out assaults, from espionage to dramatic defenses. With dozens of weapons at your disposal, you’ll be fighting against everything from helicopters to infantry, armored cars to enemy tanks, fortifications to biomechs.  The environments have been set up to be non-linear and entirely interactive. Drive where-ever you wish, crushing trees and blasting the wildlife, trashing skyscrapers, leaving tank-tracks and the bloody remains of your foes in the sand. The pyrotechnics aren’t just limited to big explosions (though there are plenty of those), as flamethrowers leave trees ablaze and foes running screaming as they burn.' FROM games WHERE igdb_id = 47098 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 47098 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('extreme-ghostbusters', 8161, '2001-05-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ugstbmocbuqeb6yolksz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Ghostbusters', 'In an attempt to takeover the world, the newly liberated and powerful ectoplasmic forces, led by the half-human, half-demon Count Mercharior, have kidnapped two key members of the Extreme Ghostbusters team. Without wasting a second, Eduardo and Kylie jump into the famous Ecto-1 ambulance and race off to the rescue... Play as Eduardo and Kylie as you uncover the clues to the kidnapping, confront the evil Count Mercharior and return your teammates, Roland and Garrett, to safety! Features: The entire universe and characters of the well-known animated series in a a brand-new adventure! Twelve exciting platform levels through four gigantic worlds! Four exhilarating car races across the busy streets of New York City!' FROM games WHERE igdb_id = 8161 ON CONFLICT (game_id, language_code) DO NOTHING;
