INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rc-revenge-pro', 43253, '2001-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48gr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6cp0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RC Revenge Pro', 'Grab the controls and hold on for dear life with the most electrifying, high-speed racing experience available. Race and wreck in enchanting movie-theme worlds, kick it into overdrive with over 30 super-flying vehicles, and blow away the competition with outrageous weapons in the most electrifying racing experience available! Previously known as Revolt 2: Pocket Rockets, this RC vehicle racer graces the 128-bit system with all the slick track designs, great weapons balance, and dead-on control that made the PC and Dreamcast versions such a hit. Luckily, developers from Acclaim''s Cheltenham Studios have taken full advantage of the PlayStatation 2 hardware--no longer will tracks be confined to suburban neighborhoods and museums. RC Revenge goes all out to deliver the goods with environments like desert islands and villages wrapped nighttime slumber. And the best part of it all? A level editor for the creative gamer is set to keep the replay value on high' FROM games WHERE igdb_id = 43253 ON CONFLICT (game_id, language_code) DO NOTHING;
