INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro: Season of Ice', 'Spyro: Season of Ice is the first Spyro game not developed by Insomniac Games and to appear on the Game Boy Advance. Unlike the Playstation series, Seasons of Ice has the player controlling Spyro through an isometric overhead camera. However, all of Spyro''s skills are still available to use, including his flame breath and glide. And the flying bonus levels make use of the Mode 7 technology in order to create the 3D like perspective.' FROM games WHERE igdb_id = 1587 ON CONFLICT (game_id, language_code) DO NOTHING;
