INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Racer', 'Choose your favourite monster from 10 fantastic creatures, each with their own ghastly traits. Choose from Mummies, Vampires, Skeletons, Werewolves and more. Confront your competitors over 10 circuits and 10 battle arenas. Help Jack O''Lantern, the pumpkin-headed man, to get his lanterns back thanks to which werewolf, witch, skeleton or vampire can find the unique way to Earth to celebrate Halloween with humans. Find the quickest champion of Halloween lands and defeat the forces of evil.' FROM games WHERE igdb_id = 20466 ON CONFLICT (game_id, language_code) DO NOTHING;
