INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biohazard ZombieBuster', 'BIOHAZARD ZombieBuster is a mobile phone game, first released in 2001 and later remastered in 2011. While the 2001 version was made available to western countries in 2006, the 2011 remake ZombieBuster was only released for Japanese mobile phones at a download price of 315 yen.' FROM games WHERE igdb_id = 356247 ON CONFLICT (game_id, language_code) DO NOTHING;
