INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Pro Wrestling D', 'The legend lives on in 2001 with a new member in the Fire Pro family. Arguably the most respected wrestling franchise in Japan, Fire Pro revives itself after Human''s (the original publisher) demise. The new features include the availability of objects to use as weapons inside and outside of the ring, an online network option, and support for up to eight players simultaneously over the net.' FROM games WHERE igdb_id = 46364 ON CONFLICT (game_id, language_code) DO NOTHING;
