INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blue-beard-2', 194787, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4l0s.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Beard 2', 'A map falls into Victor''s hands. Victor is a brave boy and the main character of this story. A place where a treasure is buried is drawn on this map. Victor goes to Africa on a steamship and gets off on an unfamiliar coast. He sets out on his hazardous journey consulting his map. Victor walks a narrow path in the jungle making his way through lianas. Growling of wild animals is heard from all sides. Suddenly someone comes down onto the path. Why, it is Victor''s old friend - the Parrot! They are very glad to see each other. Victor finds out that he is again in the same place where he has fought against the wicked thug Blue Beard not long ago.The Parrot tells Victor that Blue Beard has repaired his ship and he is going to become a pirate again. Victor tells the Parrot that he hopes to find the buried treasure with the help of the animals, of course. The friends start walking forward. Blue Beard jumps out of the bushes. He wants to know why Victor is in Africa again.' FROM games WHERE igdb_id = 194787 ON CONFLICT (game_id, language_code) DO NOTHING;
