INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Putzgrila: Mestre dos Esportes', 'Putzgrila is a sports trivia game created by journalist Milton Neves, developed by Banana Kelly Softwares, and published by Brasoft. It features more than 1.500 questions about motor racing, basketball, soccer, tennis, and volleyball. The goal is to become a master of sports but be careful not to screw up because the Rooster will always be watching you and will not forgive any serious fouls. Got a mess in the midfield? You can count on the help of the fans, or maybe the officials can also give you a hand.' FROM games WHERE igdb_id = 172472 ON CONFLICT (game_id, language_code) DO NOTHING;
