INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mech Platoon', 'The wise men say "there is no end to the truth." In this war-town place, there are two things without end - the universe and greed. Glittering stars give the impression of eternal serenity, but the reality is that they hide a lie. Among them blazes an endless war over limited resources; skirmishes that grow as the universe expands.' FROM games WHERE igdb_id = 6508 ON CONFLICT (game_id, language_code) DO NOTHING;
