INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Dungeon Dice Monsters', 'In Dungeon Dice monsters, there is a tiled board of 13 x 19 tiles (13 tiles wide) on which play is conducted. On either end of the board sits a "Monster Lord" (on the 7th tile from each side on the row closest to the players) representing either player. Each Monster Lord has 3 Life Points. The first player to lose all their Life Points loses. In the Yu-Gi-Oh! Anime, these were referred to as "Heart Points".' FROM games WHERE igdb_id = 49211 ON CONFLICT (game_id, language_code) DO NOTHING;
