INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Codename: Outbreak', 'Venom. Codename: Outbreak is a tactical 3D-shooter set in the near future. Your aim is to oppose an alien invasion on Earth and protect the human race from extermination while evil parasites continue turning people into mind-killing beasts. Together with a teammate, you play the role of an ex-Ukranian combat group member - and your primary goal is to progress through 14 action-packed single-player missions or play via multiplayer with your friends over a LAN connection.' FROM games WHERE igdb_id = 9283 ON CONFLICT (game_id, language_code) DO NOTHING;
