INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Riders: Chronicles of Pern', 'The Dragon Riders of Pern have protected their world from the alien oppressor Thread, but now they have all gone extinct. Unless you can find a new rider to take up, the world of Pern is doomed. From this point the game takes the player through four chapters with a vast storyline. Dragon Riders is a game in 3D with strong RPG and action elements. The world of Pern is based upon the novels by Anne McCaffrey. The game contains over 120 locations on three continents. The player can interact and speak with over 170 characters.' FROM games WHERE igdb_id = 132134 ON CONFLICT (game_id, language_code) DO NOTHING;
