INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('europa-universalis-ii', 682, '2001-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jr6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8pmb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Europa Universalis II', 'Europa Universalis II invites you to a global struggle for supremacy from the dark times of Jeanne D''Arc to the flaming wars of Napoleon. As the leader of a country you have to guide domestic and foreign policies. Engage in religious struggles, set up expeditions to claim the New World, lead your country to prosperity and victory. Send your Privateers to roam the seven seas, muster mercenaries to bolster your defences, and send missionaries to convert infidels to your State Religion. Interact with true historical events and persons to determine which path your nation will take in the game. The new game includes an elaborate and expanded system for diplomacy, trade, military might and development. It also includes new graphics, music, sound, manual and a new tutorial system to lower the learning curve.' FROM games WHERE igdb_id = 682 ON CONFLICT (game_id, language_code) DO NOTHING;
