INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-ball-z-mission-to-namek', 331064, '2001-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9duv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvb9w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Mission to Namek', 'In this fighting game the player takes control of three of the Z warriors as they take on the Ginyu Force on Planet Namek. The Ginyu Force is destroying 5 locations on Namek and to stop them the player must fight them one at a time using his 3 warriors. In battle, the player chooses either to attack or defend until the enemy is defeated or until the player chooses to leave the battle. The player can also have his warriors train to learn 1 of 5 techniques that they can use in battle for more damage. Once a character learns all 5 techniques he becomes a super saiyan. After all 5 Ginyu Force members are defeated the player must defeat the final boss, Frieza, to win the game.' FROM games WHERE igdb_id = 331064 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 331064 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
