INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DDRMax: Dance Dance Revolution 6thMix', 'DDRMax: Dance Dance Revolution 6thMix is the 6th game in the Dance Dance Revolution series of music video games. It was released in the arcades by Konami on October 19, 2001. Although only officially released in Japan, units exist worldwide. 6thMix contains a total of 42 songs, 36 of which are new to Dance Dance Revolution. It was the first in the series to feature Freeze Arrows. In the proto version of this game, it has some songs from DDR 1st-5th Mix. The interface used is a recoloring and smoothing of the song wheel interface first introduced in Dance Dance Revolution 5thMix, with the addition of changeable sort settings and a longer time limit.' FROM games WHERE igdb_id = 3677 ON CONFLICT (game_id, language_code) DO NOTHING;
