INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocket-power-team-rocket-rescue', 8094, '2001-09-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa0n6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Power: Team Rocket Rescue', 'Based on the successful Nickelodeon cartoon series, Rocket Power: Team Rocket Rescue for PlayStation features Otto, Reggie, Sam, and Twister displaying their Xtreme sports talents for players as they try to save Ray Rocket''s business from the competition. Since Ray Rocket''s new line of boards is not gaining exposure, the team decides to advertise by entering local competitions under his name. Players control any of the four characters to snowboard, skateboard, bike, and inline skate through 16 levels of single-player story mode, free play, or Titos Challenge. Performing tricks and completing tasks as Team Rocket tries to help Raymondo will progress players through the game. In Story Mode, the chosen character must complete tasks such as finding bike parts, collecting flags, and navigating through gates in a downhill snowbaord challenge. Performing tricks to earn high scores is another included task. Each level is timed and the tasks must be completed before the time runs out in order to win and progress to the next level. Mad Town and the ski slopes are some of the areas the team will visit in Story Mode with the main objective being to advertise the 2001 line of Rocket Boards.' FROM games WHERE igdb_id = 8094 ON CONFLICT (game_id, language_code) DO NOTHING;
