INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rhyme-rider-kerorican', 37355, '2001-01-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gk4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8w7t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhyme Rider Kerorican', 'Rhyme Rider Kerorican is a music video game in the style of Vib-Ribbon, an earlier game developed by the same studio. The game''s plot is quite simple involving the adventures of Kerorican, a female astronaut wearing kemonomimi-style frog-helmet, as she walks along accompanied by jazzy techno music. As Kerorican continues her walk, she encounters more and more enemies and obstacles. Kerorican must jump, duck, kick aside, or otherwise dodge these obstacles to progress and as she does so, the actions she takes add notes to the song such that the player''s actions results in a generative melody. By successfully clearing strings of obstacles, Kerorican''s combo count increases and this can result in a reward to the player of a crown that acts to skip the player over obstacles. This game is played with the WonderSwan Color held diagonally, the only game on the system to do so. This is why all text in the game is oblique. The game has been criticized for difficulty of gameplay as timing and tricky button combinations often result in the player''s death. The game also only contains 4 levels so replayability-value has also been considered a negative factor.' FROM games WHERE igdb_id = 37355 ON CONFLICT (game_id, language_code) DO NOTHING;
