INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('true-love-story-3', 138012, '2001-04-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pod.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Love Story 3', 'True Love Story 3 follows a male protagonist in his third year of junior high as he aims to confess his love, particularly to his longtime crush, Aotsuki Takane, whom he''s introduced to by his twin sister, Kaname. The game stands out for its high interactivity, with frequent repeated stock dialogues. Players track characters’ friendship and affection levels using a triangular chart, which they can check through Kaname. Instead of playing every day, players choose specific “try-your-best days,” which impact enthusiasm and event frequency. Its most unique feature is the detailed conversation system. On sunny weekdays, the player can attempt to walk home with a girl, triggering a complex dialogue mini-game. The goal is to raise her "heartthrob gauge" without overloading her pounding heart, and possibly score a date.' FROM games WHERE igdb_id = 138012 ON CONFLICT (game_id, language_code) DO NOTHING;
