INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('junkbot', 226067, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5shq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjw6d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Junkbot', 'Junkbot is a Shockwave puzzle-platformer that was hosted on the official LEGO website in 2001. The player must place LEGO bricks to form paths and stairways so Junkbot can reach and consume all the recycling bins in a level. The game would receive a sequel titled "Junkbot Undercover" in 2003. Despite being officially licensed by LEGO, Junkbot never appeared in any physical LEGO sets, though the "Haunted House" set from 2021 features a hidden box containing his parts.' FROM games WHERE igdb_id = 226067 ON CONFLICT (game_id, language_code) DO NOTHING;
