INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill: Play Novel', 'Silent Hill: Play Novel is an adaptation of the original Silent Hill for Game Boy Advance in the form of visual novel. It was only released in Japan, but the game has been translated and adapted into different ports by fans. Silent Hill: Play Novel is an interactive story: at certain moments the player is asked to choose between two or more possible options, which can affect the rest of the story. Besides the narration, the game features some puzzles and multiple endings.' FROM games WHERE igdb_id = 77257 ON CONFLICT (game_id, language_code) DO NOTHING;
