INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy II', 'The WonderSwan Color version of Final Fantasy II included completely redone graphics in the manner of the 16-bit generation Final Fantasy games and includes larger character sprites, remixed music by Tsuyoshi Sekito, and full graphical backgrounds in battle mode. It is from this base that the international version of Final Fantasy II began to take shape.' FROM games WHERE igdb_id = 145817 ON CONFLICT (game_id, language_code) DO NOTHING;
