INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pc-futbol-2001', 94569, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6scy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9356.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Fútbol 2001', 'PC Fútbol combines both Football Management and an Arcade simulation. The game includes 3D Match-on-line, a multiplayer game mode playable through a modem connection or TCP/IP networks, and a superb 3D simulator engine. Other features include all the major European leagues, and new additions Argentina, Holland, Scotland, Belgium and Portugal. PC Fútbol gives you the chance to both manage and play as your chosen team, offering both a stand-alone arcade game, or an in-depth managerial simulation.' FROM games WHERE igdb_id = 94569 ON CONFLICT (game_id, language_code) DO NOTHING;
