INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fisher-price-outdoor-adventures-ranger-trail', 79595, '2001-05-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ga8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fisher-Price Outdoor Adventures: Ranger Trail', 'With Ranger Rudy as their guide, children are encouraged to explore the great outdoors and play seven trailblazing activities at Camp Wonderoo. Players make a new discovery at every bend of the trail as they uncover and learn about more than 60 wildlife animals, plants, rocks, fossils, and more. With activities from stargazing to boat racing, creating cave paintings to singing around the campfire, children will gain a new respect for their environment without ever setting foot outside, and complete activities, earn badges, and search for examples of wildlife at Ranger Rudy''s request. Once they find all the items listed on Ranger Rudy''s clipboard, players are invited to test their knowledge at the Nature Match Game and ultimately earn their Junior Ranger Patch and recognition as an Official Camp Wonderoo Junior Ranger.' FROM games WHERE igdb_id = 79595 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 79595 AND c.slug = 'fisher-price' ON CONFLICT DO NOTHING;
