INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rim-battle-planets', 71747, '2001-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zpj9enwpkyftyfjgvjzl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctx5q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rim: Battle Planets', 'A human space carrier reaches the "Outer Rim" to explore new worlds, obtain powerful technology and find tracks of an ancient alien race... RIM is a 3D turn-based strategy game in the tradition of Battle Isle. It offers a simple and intuitive interface, six different races (humans, aliens, robots) and all in all 70 units with different weapons, special abilities and individual damage systems.' FROM games WHERE igdb_id = 71747 ON CONFLICT (game_id, language_code) DO NOTHING;
