INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('genso-suikoden-card-stories', 1451, '2001-09-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49li.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/phmqrfjrmdhyeabgqqhu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Genso Suikoden Card Stories', 'Set in the Suikoden universe, the game closely follows the story of Suikoden II. The hero is a young member of the Unicorn Brigade of the Highland Army. One night, your camp is attacked. You and your best friend Jowy escape, and the fate takes you into different directions, when you get involved in a war between several nations. Unlike the main Suikoden games, Gensō Suikoden Card Stories is a card-based RPG. Most of the game is spent playing a special card game with your opponents. The complex card game is not unlike a strategy battle: you have three types of cards, some of which take you to a specific "mission" (you open the game with such cards), while others represent various characters with different strengths and weaknesses. You can acquire cards in shops, get them from your opponents, and also look for them in randomly generated dungeons.' FROM games WHERE igdb_id = 1451 ON CONFLICT (game_id, language_code) DO NOTHING;
