INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('oddworld-munch-s-oddysee', 1001, '2001-11-15', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4yni.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/r5syu7lufttrglwqw4bi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oddworld: Munch''s Oddysee', 'Oddworld: Munch''s Oddysee is set in the fictional Oddworld universe and take place after those of Abe''s Exoddus. The player controls Munch as well as Abe, the hero of the previous Oddworld games. Abe''s abilities haven''t changed much since the last installment: as before, GameSpeak must be used to communicate with other creatures, leading them to safety. His fellow Mudokons can now be ordered to attack enemies. Abe can also grab and toss Mudokons or Munch to lead them to area they cannot access otherwise. Possessing enemies also comes into play, and is needed to solve many of the puzzles. Possession abilities can now be used to ignite quarrels between enemies and make them fight each other. The player can change between Abe and Munch instantly throughout most of the game. Munch brings on the table new abilities of his own: he can use his sonar to control or immobilize specific creatures, as well as swim. Another new addition is the possibility to use vending machines, which sell various items that enhance the abilities of the protagonists. At certain points Abe and Munch can also remote-control mechanical creatures.' FROM games WHERE igdb_id = 1001 ON CONFLICT (game_id, language_code) DO NOTHING;
