INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chalga Killer', 'Chalga Killer is a basic game with chalga idols. A cool idea, music, and performance. You''ll have fun, even if you''re a chalga fan! The game is made for entertainment and its sole purpose is just that! The trick in the game is to shoot as many folk guys as possible before you run out of bullets and bombs.' FROM games WHERE igdb_id = 327691 ON CONFLICT (game_id, language_code) DO NOTHING;
