INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft: My Personal Tutor Preschool & Kindergarden', 'Get a head start with all the essential skills for Preschool and Kindergarten with My Personal Tutor! There''s fun and learning from start to finish with My Personal Tutor, the only comprehensive, grade-based solution with TutorAssist learning technology (Professor Presto!). Just like a tutor, this groundbreaking technology identifies your child''s specific learning needs and offers instruction where and when it''s needed most.  This originally came in four disks for Preschool-First Grade (ages 3-7): Preschool Workshop, Alphabet Playhouse, Reader Railway, and Mathopolis.' FROM games WHERE igdb_id = 144363 ON CONFLICT (game_id, language_code) DO NOTHING;
