INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deus Ex: Game of the Year Edition', 'The year is 2052 and the world is a dangerous and chaotic place. Terrorists operate openly - killing thousands; drugs, disease and pollution kill even more. The world''s economies are close to collapse and the gap between the insanely wealthy and the desperately poor grows ever wider. The Game of the Year edition contains the latest game updates and a software development kit, a separate soundtrack CD, and a page from a fictional newspaper featured prominently in Deus Ex titled The Midnight Sun, which recounts recent events in the game''s world.' FROM games WHERE igdb_id = 25358 ON CONFLICT (game_id, language_code) DO NOTHING;
