INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario', 'Super Mario features beautiful graphics courtesy of Bill Nagel, 13 unique enemies, 64 unique background tiles (some with animation), fast scrolling, powerups like growth or flower-power, fireballs, a somewhat-challenging boss, an animated ending scene, and an expansive easy-to-use World editor that can be run on a calculator.' FROM games WHERE igdb_id = 238096 ON CONFLICT (game_id, language_code) DO NOTHING;
