INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Worms', 'A kart racing game with segmented "worms" in different colors instead of karts. Similar to older kart racing games, the game features a pseudo-3D view made up of flat sprites. The game has a racing mode where you can race against AI opponents or against another player and a battle mode for two players.' FROM games WHERE igdb_id = 347103 ON CONFLICT (game_id, language_code) DO NOTHING;
