INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes Chronicles: Revolt of the Beastmasters', 'Heroes Chronicles: Revolt of the Beastmasters is the seventh game in the Heroes Chronicles series. As all the Heroes Chronicles games, Revolt is based on the Heroes of Might and Magic III engine, and consists of a campaign and a tutorial. Unlike Heroes III, in Revolt importing extra scenarios or playing in multiplayer is impossible.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 8139 AND ge.slug = 'turn-based-strategy-tbs' ON CONFLICT DO NOTHING;
