INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Crystal of Kings', 'The Crystal of Kings is an extremely rare arcade scrolling fighter developed by BrezzaSoft. It boasts very high-quality pre-rendered graphics, and a morality system that determines whether you get a good, neutral, or bad ending. Unfortunately, the gameplay is far behind the curve, resembling Golden Axe more than advanced brawlers such as Guardian Heroes or Gaia Crusaders.' FROM games WHERE igdb_id = 39487 ON CONFLICT (game_id, language_code) DO NOTHING;
