INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maken Shao: Demon Sword', 'Maken is a man-made life form created to delve into the human soul and cure mental disease. Take control of this creature in an adventure that takes you across the globe in a battle against a terrorist organization led by a Chinese god. A 3D action adventure - Maken Shao lets you possess the bodies of key game characters, unlocking their memories and special attacks as you struggle to uncover who is behind a sinister conspiracy to change the fate of humankind forever.' FROM games WHERE igdb_id = 43421 ON CONFLICT (game_id, language_code) DO NOTHING;
