INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tile World', 'Originally developed as a homebrew port of the Windows port of Chip''s Challenge for Linux, it caught the attention of that game''s original dev, Chuck Sommerville, who asked if the Linux port could be made playable on Windows as well. Tile World supports the original level packs from Chip''s Challenge on top of including hundreds of original levels.' FROM games WHERE igdb_id = 131408 ON CONFLICT (game_id, language_code) DO NOTHING;
