INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar Wing: Toki wo Koeta Seisen', 'Lunar Wing - Toki wo Koeta Seisen is a love-themed strategy RPG in which players take part in battles using the game''s active time simulation battle system while attempting to earn the affection of bishojo ( used to refer to young and pretty girls, usually below university age) characters.' FROM games WHERE igdb_id = 138970 ON CONFLICT (game_id, language_code) DO NOTHING;
