INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jak and Daxter: The Precursor Legacy', 'Jak and Daxter: The Precursor Legacy is a 2001 platform video game developed by Naughty Dog and published by Sony Computer Entertainment for the Sony PlayStation 2 on December 4, 2001, as the first game of the Jak and Daxter series. The game follows the protagonist, a young teenager named Jak, as he tries to help his friend Daxter after he is transformed into an "ottsel", a fictional hybrid of an otter and a weasel. The game offers a large range of missions, collectables and objectives, often in the form of minigames, which provide a variety of gameplay experiences, as well as puzzles and platforming stages, which are completed by the player to proceed with the story.' FROM games WHERE igdb_id = 1528 ON CONFLICT (game_id, language_code) DO NOTHING;
