INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'E-Police', 'A phone game, produced by Bandai and developed by Tambourine. The player would unravel a mystery by communicating with the fictional police force through text messages. The soundtrack for the game was composed by Shingo Yasumoto (one half of TORN, the duo he created alongside Masafumi Takada to compose the Flower, Sun, and Rain soundtrack) and produced by Grasshopper Manufacture, who also released it as a music CD under their GhM Records label. The game itself is lost.' FROM games WHERE igdb_id = 341531 ON CONFLICT (game_id, language_code) DO NOTHING;
