INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 2002', 'NBA Live 2002 is the 2002 installment of the NBA Live video games series. The cover features Steve Francis as a member of the Houston Rockets. The game was developed by EA Sports and released on October 29, 2001 for the PlayStation 2, October 30, 2001 for the PlayStation and November 18, 2001 for the Xbox. This game was commentated by Don Poier and former NBA player Bob Elliot.[citation needed]' FROM games WHERE igdb_id = 5950 ON CONFLICT (game_id, language_code) DO NOTHING;
