INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Tamers: Pocket Culumon', 'In this final entry of the Pocket Digimon sub-series, you can interact with Culumon, that little Digimon from Digimon Tamers anime series. Unlike in the previous Pocket Digimon games, you can only get Culumon to your PocketStation. Also, Culumon can not evole at all.' FROM games WHERE igdb_id = 108939 ON CONFLICT (game_id, language_code) DO NOTHING;
