INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Rules: Get Phat', 'One Eye Jack, a badass little skate fiend and leader of the No Rules posse, must stop an alien invasion of his local hangouts. To achieve his goal, he must board like a pro, be a dead-eye shot with his slingshot and alien slime gun, and grind the rails of social irresponsibility-all in the name of preserving his lifestyle.' FROM games WHERE igdb_id = 6525 ON CONFLICT (game_id, language_code) DO NOTHING;
