INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 56: The Sniper', 'An entry in the Simple 1500 series for PlayStation where players are challenged to snipe targets. A number of missions will give players the ability to choose their sniping position and the time of day they choose to execute their hit. Despite being released as a Japan-exclusive, the game would receive a sequel with an official English release; 2004''s The Sniper 2 for the PlayStation 2.' FROM games WHERE igdb_id = 57130 ON CONFLICT (game_id, language_code) DO NOTHING;
