INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Island 2: The Brickster''s Revenge', 'The Brickster is back and out to cause more mischief in this wild, racing, chasing, island-hopping sequel. In your quest to piece together The Informaniac''s Constructopedia, you''ll drive, scuba-dive, fly a place and even ride a dinosaur as you chase the Brickster down through these amazing new LEGO worlds. Meet all kinds of fun characters along the way as you journey through the game. You''ll need all your skills to solve the puzzles and achieve your ultimate goal, to prevent LEGO Island being ruined.' FROM games WHERE igdb_id = 5616 ON CONFLICT (game_id, language_code) DO NOTHING;
