INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Fighter 4', 'Virtual Fighter 4 is the fourth game in the Virtua Fighter series. In Japan, Virtua Fighter 4 is famous for spearheading and opening the market for internet functionality in arcades. VF.NET started in Japan in 2001, and since companies have created their own arcade networks, e-Amusement by Konami, NESiCAxLive by Taito and Square Enix, and ALL.Net by Sega and Bandai Namco.' FROM games WHERE igdb_id = 1552 ON CONFLICT (game_id, language_code) DO NOTHING;
