INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Wing Blitz', 'Blue Wing Blitz is a traditional turn-based tactical role-playing game, although it has the particularity of involving mostly aerial warfare units. These are moved on a grid map, and an encounter with an enemy unit opens a separate, close-up combat screen in which up to two ally units and two enemy units engage in a short dogfight; the player using menu commands to attack, change altitude or take evasive maneuvers.' FROM games WHERE igdb_id = 37457 ON CONFLICT (game_id, language_code) DO NOTHING;
