INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mister-mosquito', 8966, '2001-06-21', 57, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ssc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7m4j.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mister Mosquito', 'The Yamada family will never know what bit them. You are Mister Mosquito, an uninvited guest in the Yamada''s family home in Japan. In order to store up enough food for the coming winter, you will need to drink as much of their precious blood as possible while they are in bed, talking on the phone, watching tv, or even taking a bath. The Yamada family knows you are in the house, and they have plans to take you out. Deadly insecticides fill the air, and members of the family have the ability to crush you like a bug. You want a taste of their plasma. They want you dead. Something''s gotta give.' FROM games WHERE igdb_id = 8966 ON CONFLICT (game_id, language_code) DO NOTHING;
