INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-6thmix-the-uk-underground-music', 79612, '2001-07-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ce0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ed4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania 6thMix: The UK Underground Music', 'beatmania 6thMIX is a rhythm game developed by Konami. It is the eleventh game in the beatmania series and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. The ANOTHER difficulty has been renamed to MANIAC. HARD mode is no longer a separate mode, but a selection on the song selection screen.Song titles in the selection screen is now colored due to diffuculty, NORMAL is yellow, HARD is red, MANIAC is green. EXPERT+ mode is introduced, featuring extra hard courses. FREE mode introduced, allowing players a free selection of the music regardless of difficulty. A session is limit to 3 stages instead of NORMAL mode''s 4 stages. The modifiers selection is now also available in NORMAL and FREE mode, not only in EVENT mode as in CORE REMIX. As with other trilogy starters, all older songs have been removed. 27 brand new songs are introduced with a focus on the UK music scene.' FROM games WHERE igdb_id = 79612 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 79612 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
