INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steven Gerrard''s Total Soccer 2002', 'Take your team to the dizzy heights of the 2002 club and international football season with Steven Gerrard''s Total Soccer 2002. Test your ball control: tackle, head, dribble, pass and score with amazing realism. Compete in all major European league competitions with real players, including the English League, Italian League, French League, Spanish League, German League, Dutch League, and 38 national teams. Play in European Club, Club World Cup, World Cup, or customize your own league, cup, or friendly matches. Also features a two-player mode that lets you challenge your friends via the Game Boy Advance Game Link cable.' FROM games WHERE igdb_id = 49249 ON CONFLICT (game_id, language_code) DO NOTHING;
