INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mythical-warriors-battle-for-eastland', 210109, '2001-12-31', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdnh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mythical Warriors: Battle for Eastland', 'The countries of Draco and Phoenix have come to blows in Eastland, the land of the gods. After an uneasy peace, they have both decided to conquer the entire land. But is it their own idea, or has the wizard Horus corrupted them both? Battle for Eastland is a real-time strategy game, with a large number of magical forces. Each of the two sides has a distinct class list, and ranges from the basic (shamans and warriors), to the magical (dragons and golems). In total, 30 different troops are included. In addition, as a powerful wizard, you have the ability to drop game-changing spells on the battlefield, running off a recharging mana bar. By having your troops kill enemies, you will increase in level, which gives you access to the higher-end troops, spells, and research. Your experience is kept between battles in the campaign and skirmishes, opening up new tactics as time goes on. Single-player campaigns for both Draco and Phoenix are included, and previous levels may be replayed at any time. Also, 16 multi-player and skirmish maps are included. Finally, a level editor will let you create your own levels.' FROM games WHERE igdb_id = 210109 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 210109 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
