INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thomas & Friends: Railway Adventures', 'Engineers Wanted! Spend the day on the railway with Thomas & Friends! Now you can play engineer and drive Thomas! Blow the whistle, set the throttle, switch tracks, and talk to other characters - it''s going to be a busy day on the Island of Sodor! Use your Thomas the Tank Engine Playset to help deliver passengers for Bertie, repair landslide damage with Harold, find and sort the mail - plus a whole lot more! Travel with Thomas through four fun adventures filled with activities, games and cool print features for off-computer play. Clickity-clack, Thomas is back and you''re in control!' FROM games WHERE igdb_id = 355515 ON CONFLICT (game_id, language_code) DO NOTHING;
