INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Golf', 'Virtua Golf, known as Dynamic Golf in Japan, is a Sega NAOMI golf simulator which uses a trackball controller. A Sega Dreamcast version was planned, but was later removed from Sega''s release schedules without warning. No other home version of the game has ever been released. Sega Logistics Service announced it would end service on the arcade machines on March 31, 2017' FROM games WHERE igdb_id = 131345 ON CONFLICT (game_id, language_code) DO NOTHING;
