INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Wolverine''s Rage', 'X-Men: Wolverine''s Rage is a side-scrolling video game designed for the Game Boy Color. The game''s plot centres around Wolverine as he pursues Lady Deathstrike, Sabretooth, and Cyber. Upon discovering schematics that enable her to construct a weapon capable of melting Wolverine''s adamantium skeleton, Lady Deathstrike resolves to proceed with the machine. Wolverine must undertake any necessary actions to locate her and prevent the impending threat.' FROM games WHERE igdb_id = 49899 ON CONFLICT (game_id, language_code) DO NOTHING;
