INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('noctis', 94528, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ima.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5ruo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noctis', 'Noctis is a computer space flight simulator featuring first-person visual exploration of an imaginary galaxy. The player is manifested in Noctis as the pilot of spacecraft called a Stardrifter, capable of instantaneous interstellar travel. This allows travelling between stars, refuelling the Stardrifter from Lithium ion-ejecting stars, approaching planets in star systems and their moons, and even landing where it is physically possible. Many planets feature atmospheres and weather effects. Some harbour plants and animals, or even mysterious ruins. No goal or measure of success is imposed by the game: it simply allows the player to catalogue and annotate the player''s discoveries in a common database of stellar bodies called the GUIDE, which is to be synchronised over the author''s Internet server.' FROM games WHERE igdb_id = 94528 ON CONFLICT (game_id, language_code) DO NOTHING;
