INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Illbleed', 'Illbleed is a tongue-in-cheek survival horror game and a send-up to horror Clichés. Despite being financially unsuccessful, this game received a worldwide cult following for its notable combination of nonlinear gameplay elements (e.g. trap detection) and bizarre B-movie style comedy horror theme, dialogue and voice acting.' FROM games WHERE igdb_id = 26450 ON CONFLICT (game_id, language_code) DO NOTHING;
