INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Mutant Academy 2', 'X-Men: Mutant Academy 2 is a PlayStation video game, the sequel to X-Men: Mutant Academy. Both feature the X-Men in a 3-D fighting arena similar to Mortal Kombat 4. Like its predecessor, the game allows the player to select from several heroes and villains and includes many of the signature moves from the comic. The game also includes a behind-the-scenes look at X-Men: The Movie concept sketches, costumes and other similar material.' FROM games WHERE igdb_id = 4110 ON CONFLICT (game_id, language_code) DO NOTHING;
