INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ducati World: Racing Challenge', 'In this Ducati brand-licensed motorcycle game, players can race a range of Ducati bikes ranging from the 1960''s Daytona 350 to the 748 and 996. The game includes a career mode (Ducati Life) where players climb the ladder to earn four different licenses, buy better bikes and accessories such as helmets, leathers and bike customizations. Regular quick races feature and arcade mode, two player split-screen, time attack and regular races. New tracks can be unlocked and are stored in the Rewards menu.' FROM games WHERE igdb_id = 45856 ON CONFLICT (game_id, language_code) DO NOTHING;
