INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steppenwolf: The X-Creatures Project', 'Steppenwolf: The X-Creatures Project is a 2001 episodic action-adventure video game developed by Sarbakan and published by Warner Bros. Studios. The game centers around two characters, Meg Crimson and Alan "Steppenwolf" Kane, as they journey around the world in search of the blood samples of various cryptids rumored to have been alive for hundreds of years, all in an effort to finish the X-Creatures Project, an operation designed to grant humans immortality. The gameplay often revolves around collecting items and interacting with the open world in an attempt to solve a mystery or escape a dangerous situation. In-game quick cut scenes are used to show the effect of an action. The game is split into six chapters, with each consisting of a prologue, four episodes, and, with the exception of the final chapter, a recap.' FROM games WHERE igdb_id = 284584 ON CONFLICT (game_id, language_code) DO NOTHING;
