INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konohana: True Report', 'Konohana: True Report is the first entry of the mystery visual novel series Konohana, taking place in a high school featuring Meguru Momoi as a protagonist, a second-year student who just moved to Konohana high school. As things would have it, what you thought to be the peaceful period until graduation turns into a suspense thriller.' FROM games WHERE igdb_id = 213703 ON CONFLICT (game_id, language_code) DO NOTHING;
