INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sword-and-fairy-inn', 78048, '2001-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/svfsyqbeeqtfxmnu0skz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar28cm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword and Fairy Inn', 'Sword and Fairy Inn (Xianjian Kezhan) is based on the Chinese role-playing game Xianjian Qixia Zhuan. The game has the same protagonist, the young swordsman Li Xiaoyao, and is in a certain way a parody of Sword and Fairy. In this game, Li Xiaoyao still works for his aunt, doing various jobs in the inn. The game also features the female characters from the RPG - Li Xiaoyao''s sweetheart Zhao Ling''er, Lin Yueru, and Anu. Unlike most installments in the series, "Sword and Fairy Inn" is not a role-playing game, but a simulation. The player''s goal in the game is to cook meals, prepare rooms, and generally take care of the guests. The game has an internal clock, and the hero should do his job well to please his aunt. When Li Xiaoyao is not busy with the inn, he can explore nearby locations or have a date with Ling''er. There are many items to be found, which can be later used for cooking and other purposes. The game has pre-rendered backgrounds and "super-deformed" graphics for characters.' FROM games WHERE igdb_id = 78048 ON CONFLICT (game_id, language_code) DO NOTHING;
