INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tactics Ogre: The Knight of Lodis', '"Highlights and Key Features: - Over 40 hours of gameplay and multiple endings! - Discover powerful character classes with the new Emblem System! - Cast a wide assortment of magic spells to defeat the enemy! - Go head-to-head against a friend by using the Game Boy® Advance Game Link® cable! - All new Quest Mode enables you to discover hidden items and weapons not available in the main game. - Utilize the Exchange Mode to trade items, spell books and characters with a friend. - Save up to 3 games!"' FROM games WHERE igdb_id = 6635 ON CONFLICT (game_id, language_code) DO NOTHING;
