INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Soccer', 'Pocket Soccer is a Sports game, developed by Game-Play Studios and published by Nintendo, which was released in Europe in 2001. It''s time to show your soccer skills! Pocket Soccer brings the world''s most popular sport direct to the palm of your hand. Create your own team from more than 200 players or choose from 32 ready made teams, then work your way up the league in this fast paced game! Play head-to-head with a friend using the Universal Game Link cable or trade players in order to make your team the very best!' FROM games WHERE igdb_id = 50009 ON CONFLICT (game_id, language_code) DO NOTHING;
