INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Fox 3: Operation Ozone', 'A huge hairspray space station is blasting vile vapors into the ozone, putting Earth at the mercy of the sun''s rays. With her paw on the nozzle, Poodles Galore unleashes her plot to corner the sunscreen market. It''s up to SPY Fox and his friends to "can" Poodles and save the planet.' FROM games WHERE igdb_id = 7653 ON CONFLICT (game_id, language_code) DO NOTHING;
