INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wario-land-4', 1699, '2001-08-21', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wpx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kt5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wario Land 4', 'Wario''s back for more...and more...and MORE! Hey! You! Yeah, you! Listen up when Wario''s talking to you! I just read about this legendary Pyramid of Gold, and you''re gonna help me go explore it. There''s lots of treasure in there for the taking, and I want it all. I''m sure there are gonna be all kinds of weird enemies and big, bad bosses in there, so if you don''t think you can hack it, put the game down now. I don''t want any losers making me jump into bottomless pits, you hear me? -Wario invades the Game Boy Advance! See Wario in all his greedy glory as he explores vivid worlds made possible by the power of the GBA! -Flex your muscles! Wario is no longer immortal, so you''ll have your work cut out as you roll, punch and jump your way to tougher and tougher challenges. Wario will get stung by bees, zombified, bitten by bats, set on fire, and much more - what a way to make a living! -Over twenty enormous stages await! Hunt down CDs for your listening pleasure, or collect treasure to spend on all-new items that you can use against the most bizarre bosses ever!' FROM games WHERE igdb_id = 1699 ON CONFLICT (game_id, language_code) DO NOTHING;
