INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R/C Helicopter: Indoor Flight Simulation', 'RC Helicopter Indoor Adventure is a RC helicopter flight simulation. You have to navigate your way through rooms, hallways and corridors collecting points to gain access to bigger and faster helicopters. There are no enemies, just you, rc helicopter, ticking time and some obstacles. There are 2 game modes: challenge and adventure. Challenge contains missions and in adventure you have to collect stars.' FROM games WHERE igdb_id = 61826 ON CONFLICT (game_id, language_code) DO NOTHING;
