INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR Racing 4', 'NASCAR Racing is back for 2001 better than ever! For the first time for NASCAR game, the Daytona track! Arcade racing mode for the novices, simulation mode for the experts, multiplayer mode for up to 32 players. Improved physics model, improved graphics engine with real-time shading. Improved radio chatter, ability to tell pit crew what to do before you pit... And much more.' FROM games WHERE igdb_id = 806 ON CONFLICT (game_id, language_code) DO NOTHING;
