INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Looney Tunes: Sheep Raider', 'Stealth, humour and tactical skills - the scene is set for the ultimate showdown between Sam Sheep-dog and a greedy wolf whose only thought is where his next meal is coming from. Take control of Ralph Wolf as he uses his ACME arsenal to solve perplexing platformer puzzles all in the name of stealing a sheep — live on Daffy Duck''s new game show: Sheep, Dog, and Wolf.' FROM games WHERE igdb_id = 44884 ON CONFLICT (game_id, language_code) DO NOTHING;
