INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('speedboat-racing', 144387, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6k2q.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedboat Racing', 'Speedboat Racing is a racing game where players can race with speedboats through the canals of Venice and Amsterdam. For every race, players can choose a certain boat with a captain that all have their own strengths and weaknesses. The game contains three different game modes: Championship, Quickrace and Sightseeing.* Championship is a career mode where players have to complete and win several pre-determined races to become the ultimate champion. This mode has to be played in order to unlock more boats. Quickrace is a mode where the player can choose the location and boat and complete the race. No statistics are being collected from this mode. In Sightseeing, the player can freely roam the different maps and sail through the canals, discovering the regions and buildings around. There is no race to complete in this mode and this mode only ends when the player quits to the main menu. Players can not only race the computer opponents, but also hinder them by using torpedo''s or guided missiles, temporarily disorienting them or blowing them into an other direction. Coiled springs can be collected to jump out of the water and over something. The player can also collect turbo''s to temporarily boost the speed of the boat.' FROM games WHERE igdb_id = 144387 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 144387 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
