INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Evolution Soccer', 'Pro Evolution Soccer, often abbreviated as PES and also known as World Soccer: Winning Eleven 5 in Japan and North America, is a football sports simulation video game released in 2001. It is the first instalment of Konami''s Pro Evolution Soccer series. World Soccer: Winning Eleven 5 Final Evolution was also released in Japan after Pro Evolution Soccer was released in Europe.' FROM games WHERE igdb_id = 4642 ON CONFLICT (game_id, language_code) DO NOTHING;
