INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x-men-reign-of-apocalypse', 6688, '2001-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zgg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq16f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Reign of Apocalypse', 'You and your fellow X-Men are lost in an alternate reality, only to discover that supervillain Apocalypse reigns supreme. Not only do you find yourself at the mercy of his minions, but also the line between foe and friend is dangerously blurred in this mirror universe. Your only hope is to fight your way through numerous enemies and threats until you reach the Warp Gate and return home. Will you survive long enough to make it there? X-Men: Reign of Apocalypse is the first X-Men game released for the Game Boy Advance platform. It offers side-scrolling gameplay combined with fighting-game action. Best of all, you become your favorite X-Men character--Wolverine, Cyclops, Storm, or Rogue--and do battle using the character''s signature moves. While in story mode, you''ll battle Apocalypse''s minions as you try to return to your own dimension. In versus mode, you can compete head-to-head in a deathmatch or join forces to battle enemy hordes, unlock X-Men friends, and capture the flag. Reign of Apocalypse''s fighting system lets you score experience points using your brute strength and special mutant powers. At the end of each level, you can use these points to increase your damage potential, agility, or mutant power to unleash the ultimate X-Man!' FROM games WHERE igdb_id = 6688 ON CONFLICT (game_id, language_code) DO NOTHING;
