INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('espn-x-games-skateboarding', 6398, '2001-09-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3g93.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ESPN X Games Skateboarding', 'he X Games could be considered the Olympics for Generation X, and now one of the premier events skateboarding has made its way to the Game Boy Advance with ESPN X GAMES SKATEBOARDING. Choose from eight pro skaters Bob Burnquist, Carlos DeAndrade, Chad Fernandez, Kerry Getz, Rick McCrank, Colin McKay, Chris Senn, and Lincoln Ueda and 64 licensed decks as you get ready to shred on the streets, sidewalks, handrails, and more. There will be three cities to skate in San Francisco, New York, and Los Angeles each with location-specific elements and landmarks. The game consists of nine levels, broken into three categories: X Games competition, street skating, and fantasy. The 12 big-name bands including Linkin Park, Voodoo Glow Skulls, and New Found Glory will provide the adrenaline-pumping tunes to keep the action fast and furious. Get ready to ollie, grind, and kickflip your way to victory with ESPN X GAMES SKATEBOARDING.' FROM games WHERE igdb_id = 6398 ON CONFLICT (game_id, language_code) DO NOTHING;
