INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wave Race: Blue Storm', 'Racing atop a bed of dynamically changing waves, gamers must navigate their way through eight different environments under random weather conditions, including the powerful and visually impressive Storm setting. Play through, tutorial stunt, time trial challenges, and Championship mode, which offers shortcut-laden Normal, Hard, and Expert circuits, sending you and seven other racers around eight different course environments loaded with buoys.' FROM games WHERE igdb_id = 4232 ON CONFLICT (game_id, language_code) DO NOTHING;
