INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ricochet-xtreme', 70421, '2001-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99lk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6evm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ricochet Xtreme', 'Ricochet Xtreme is the first game of the Ricochet franchise by Reflexive Entertainment. Although the base gameplay is like Breakout, it takes much more from Arkanoid. A fast-paced action Breakout remake that challenges your agility and reflexes, Ricochet Xtreme boasts a whopping 170 levels of intense competition. Featuring four levels of difficulty and a multitude of power-ups and obstacles to dodge, each level provides endless excitement. Whether you''re a beginner or an expert in the genre, you''ll find a challenge that''s just right for your skill set. Enjoy blasting through this futuristic world at blazing speeds while avoiding treacherous hazards with surgical precision – all while keeping your eye on the ball. Ricochet Xtreme stands out with its unique combination of bonus rounds, one-of-a-kind power-ups and obstacles tailored to keep even veterans on their toes. The graphics are smooth and vivid, making it an immersive experience not to be missed by any Breakout enthusiast. There''s always something new to explore as well as epic showdowns to be had, so get ready for some intense ricocheting action.' FROM games WHERE igdb_id = 70421 ON CONFLICT (game_id, language_code) DO NOTHING;
