INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waterloo: Napoleon''s Last Battle', 'Waterloo captures the excitement of the early 19th-century battle with all the color, pomp, and pageantry of the Napoleonic era. Take command ofNapoleon''s troops or Wellington''s army and change history in this epic game based on Sid Meier''s Gettysburg engine. There are over 30 historical and speculative scenarios depicting all phases of the battle. The game also allows you to design your own battles: pick your own forces and battle objectives for unlimited play.' FROM games WHERE igdb_id = 71611 ON CONFLICT (game_id, language_code) DO NOTHING;
