INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('more-pie', 108717, '2001-06-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6rcz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'More Pie', 'Roll out your pie dough, cut & trim it, mix pie filling, bake, slice, decorate, eat and share virtual pies on your iPod Touch, iPad, or iPhone. More Pie gives you an entire kitchen full of possibilities. Browse the cookbook to pick your pie recipe, with 20 kinds to choose from. Pick from favorites like apple, blueberry, cherry, pumpkin, chocolate cream, pecan, coconut, peanut butter, grasshopper and more. Then make your crust, either rolling out the dough, or making a graham cracker or cookie crust. Mix all the ingredients for your pie filling, put it in the pie pan, and then get ready to bake. Once your pie is done, you can slice it, pick a slice and add 30+ toppings including whipped cream, different flavors of ice cream, fruit, sprinkles, and more. And finally take bites of the pie or email a picture of the whole pie or slice to a friend.' FROM games WHERE igdb_id = 108717 ON CONFLICT (game_id, language_code) DO NOTHING;
