INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tekkouki-mikazuki-taikenban', 269148, '2001-07-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gx4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tekkouki Mikazuki Taikenban', 'Tekkouki Mikazuki (Taikenban) (鉄甲機ミカヅキ) is a Action video game published by Media Factory and developed by Sandlot released on March 2nd, 2001 for the PlayStation 2. This is the Trial Edition, "Taikenban" in Japanese language. Full game was never released since the series never took off, only this version exists. It came in a box set along with the series'' original soundtrack. The engine of the game was eventually used for RAD: Robot Alchemic Drive.' FROM games WHERE igdb_id = 269148 ON CONFLICT (game_id, language_code) DO NOTHING;
