INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Road Race', 'Take to the road in this white-knuckle thriller of from Taito. Choose from a wide selection of Japanese car manufacturers to race, from regular family saloons, to high powered rally cars. Contend with the varying conditions that courses throw at you, from the early morning mist to snow covered terrain. Features include six different car manufacturers, 40 various automobiles, ten courses, and three game modes.' FROM games WHERE igdb_id = 43303 ON CONFLICT (game_id, language_code) DO NOTHING;
