INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL QB Club 2002', 'NFL QB Club 2002 is a football video game developed and published by Acclaim Entertainment under their Acclaim Sports banner. It is the final game in Acclaim''s NFL Quarterback Club series. Some of the game''s key features are: NFL Quarterback Challenge mode, featuring four head-to-head events: Speed and Mobility, Accuracy, Long Distance Throw and Read & Recognition. Unlock retired players like John Elway, Dan Marino, Steve Young, Jim Kelly and Phil Simms 31 NFL clubs and over 1500 NFL players. Play-by-play from Kevin Harlan and color commentary from Bill Maas. Player models feature blinking eyes, jaw motions, facial expressions and removable helmets. Player injuries, penalties and weather conditions affect season play and individual player performance. 5 modes of play: Season, Exhibition, Challenge Mode, Playoffs, and Pro Bowl' FROM games WHERE igdb_id = 4040 ON CONFLICT (game_id, language_code) DO NOTHING;
