INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-final-four-2002', 68262, '2001-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/knlme7je7bvkgx1yigwf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Final Four 2002', 'The follow-up to Final Four 2001 features the obligatory roster updates with over 300 real NCAA teams and 31 conferences with authentic fight songs and 70 new player models to give the game a feel of realism. The standard modes apply such as Exhibition that supports both one-player or two-player and a Dynasty mode that lets the player compete in a full-season in order to secure a place in the 64-team tournament known as "March Madness". It also features the voice talents of Eddie Doucette and Billy Packer who provide play-by-play commentary.' FROM games WHERE igdb_id = 68262 ON CONFLICT (game_id, language_code) DO NOTHING;
