INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Night of the Living - Treehouse of Horror', 'The Simpsons: Night of the Living - Treehouse of Horror is a platform game for the Game Boy Color. The game features seven side-scrolling levels in which the player controls the members of the Simpson family. The game features seven levels, each one of which re-creates a tale from the annual Treehouse of Horror episodes. All five members of the Simpson family have their own level, except for Homer who has three.' FROM games WHERE igdb_id = 2840 ON CONFLICT (game_id, language_code) DO NOTHING;
