INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('canary-kono-omoi-wo-uta-ni-nosete', 269412, '2001-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co75s2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Canary: Kono Omoi wo Uta ni Nosete', 'Port of the eroge Canary ~My Feelings into a Song~ without adult content. A young man moves to Shikoku, the smallest of Japan''s four main islands, to live in Kagawa prefecture with his uncle who runs a sound studio. Attending the Kotohira Middle School as a student with an ear for music, the player engages in interaction with seven female students who play in the school band. Some girls specialize in vocals and others wield instruments in the pop section. Music provides the glue for possible friendships and amorous maneuvers. A supporting cast of other characters including classmates, teachers and your uncle also supply additional interaction and bolster the storyline. The bulk of the interaction leads up to the school festival where you and band members hope to create beautiful music together. Mika Katagiri wants her band to perform at the upcoming local festival. However, complications arise. Their keyboardist, Jun, refuses to play, and their stage has been cancelled. Refusing to give up, Mika and her band strive to find a way to play at the festival, using any means necessary.' FROM games WHERE igdb_id = 269412 ON CONFLICT (game_id, language_code) DO NOTHING;
