INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fuzion Frenzy', 'Fuzion Frenzy is a launch title for the Microsoft Xbox. At its core, Fuzion Frenzy is a four-player party game featuring 45 different mini-games (not including the titular Fuzion Frenzy). A demo of the game was included with some other launch titles in the US, including Halo, Munch''s Oddysee, the first Project Gotham Racing game and Amped. The title was among the first to be released as a part of the Xbox Originals program. A sequel was later released for the Xbox 360, entitled Fuzion Frenzy 2.' FROM games WHERE igdb_id = 5842 ON CONFLICT (game_id, language_code) DO NOTHING;
