INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Smash Bros. Melee', 'Super Smash Bros. Melee is the second installment in the Super Smash Bros. series and the follow-up to the Nintendo 64 title. It includes all playable characters from the first game, and also adds characters from franchises such as Fire Emblem, of which no games had been released outside Japan at the time. Super Smash Bros. Melee builds on the first game by adding new gameplay features and playable characters: it''s major focus is the multiplayer mode, while still offering a number of single-player modes.' FROM games WHERE igdb_id = 1627 ON CONFLICT (game_id, language_code) DO NOTHING;
