INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nakoruru: Anohito kara no Okurimono', 'Nakoruru: Ano Hito kara no Okurimono, abbreviated as "Nakorimo" or Nakoruru ADV internationally, is an adventure game developed by Inter-lets as a spin-off of the Samurai Shodown series. It was released on July 6, 2001 in Japan for the Windows operating systems and later for the Sega Dreamcast. The game was scheduled to be available at the same time as Samurai Shodown: Warriors Rage but experienced several setbacks due to the game''s changing sponsors.' FROM games WHERE igdb_id = 57624 ON CONFLICT (game_id, language_code) DO NOTHING;
