INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Monster II', 'Pocket Monster II is a platform game for the Mega Drive, probably made by DVS Electronic Co., and the sequel to Pocket Monster, also by DVS. Unlike the first game, no SNES port has yet been discovered. This game is a significant improvement over the original. The artwork and audio has improved since the first game, though the former is still mostly stolen from other games. The music is mostly remade from the Japanese Pokémon TV series, with songs including the original Japanese opening theme (Stage 1 and Stage 4) and the ending theme of the pilot. (Boss theme.)' FROM games WHERE igdb_id = 45691 ON CONFLICT (game_id, language_code) DO NOTHING;
