INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lma-manager-2002', 22542, '2001-11-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7h0u.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LMA Manager 2002', 'LMA 2002 was the final version in the series to be released on PlayStation, launched in October 2001. Although chiefly just an update from the 2001 version, the game did prove to be quite a stepping stone from the LMA of old and the LMA seen today. The first PlayStation 2 incarnation went under the same name when released in April 2002. A significant update from PS1, it allowed players to manage in one of six European leagues, all of which were processed by the game simultaneously (the top two divisions in Italy, Spain, Germany and France were added, in addition to the existing top four divisions in England and Scotland). On the PS2, matches played out in full in a 3D match environment, followed by post-match highlights voiced by famous BBC presenter Gary Lineker alongside the returning Hansen. The game play advanced in this game from the 2001 version, in particular the in-match style. Players tend to shoot early, from around thirty yards, rather than enter into the penalty area.' FROM games WHERE igdb_id = 22542 ON CONFLICT (game_id, language_code) DO NOTHING;
