INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eve-zero-ark-of-the-matter', 71277, '2001-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31j2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sca59l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EVE Zero: Ark of the Matter', 'Eve Zero is a prequel to Eve Burst Error. Once again, the player controls the two main heroes of the series: the witty and womanizing private investigator Kojiroh Amagi, and the beautiful red-haired secret agent Marina. The events of the game take place shortly before those of Eve Burst Error. Kojiroh is working at Katsuragi Detective Office together with his girlfriend Yayoi. Dr. Nishina, the head of a genetic research facility, hires Kojiroh to investigate the disappearance of his son Shin. At the same time, Marina receives an assignment from her boss Kohno, which involves watching over a representative of an American company. As in all EVE games, the two stories appear unrelated in the beginning and are gradually linked together later in the game. The player needs to switch between the two protagonists frequently in order to advance in the game. The interface consists of a menu that makes it possible to interact with the game world. Beside the traditional "Look", "Talk", and "Go" commands, there are many others, specific to the situation. Being a Japanese-style adventure game, Eve Zero does not feature any puzzles.' FROM games WHERE igdb_id = 71277 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 71277 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
