INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Shadow of Zorro', 'The Shadow of Zorro is a video game based on the character Zorro for PlayStation 2 and PC. Shadow of Zorro has received generally poor reviews. Futuregamez.net awarded the game 49% stating that the game "seems very underdeveloped with poor level structures." A 3D action/adventure game, The Shadow of Zorro is a stealth-based romp through 28 different locations and sports over 700 different animated cut scenes.' FROM games WHERE igdb_id = 27627 ON CONFLICT (game_id, language_code) DO NOTHING;
