INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-haste', 14734, '2001-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hyzgakxh64g4tiv0rr2r.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Haste', 'Most of us driving-game junkies want more than a realistic driving experience; we want rocket-like speed that lets us blast through the streets, defying the boundaries of realism. Space Haste seats you in a hovercraft modelled after 50s-style cars, in a race where your speed limit is unlimited. The maximum speed of the hovercraft increases throughout the game, as your skills improve. What makes this even more challenging is that your reaction time decreases as your speed increases, so hugging the curves of the track gets even more difficult. Along the track, you can grab pickups, such as Cloak, Stun, and Shield, that add temporary powers to your vehicle.' FROM games WHERE igdb_id = 14734 ON CONFLICT (game_id, language_code) DO NOTHING;
