INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-rancher-3', 43631, '2001-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69hj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Rancher 3', 'Monster raising and creature contests move into the 128-bit generation as the popular Tecmo series sets up shop on the PlayStation 2 in this release of Monster Rancher 3. Though many characters and places are recognizable from earlier releases in the series, monsters in this game are represented in a cel-shaded cartoon style, similar to that of the Dreamcast''s Jet Grind Radio or the contemporary PS2 release Yanya Caballista featuring Gawoo. The game receives improved graphics and some additional features with its move to the more powerful PS2 console. Most of the rules of play and monster-raising conventions established in earlier games remain in this version. Monsters develop according to the training and treatment they receive and players are encouraged to explore the game world to find new training opportunities. Players can generate monsters using other forms of media, as the game creates creatures according to data on music CDs and movie DVDs. While some aspects of creation are random, certain albums and movies may generate creatures specifically related to the artistic content on the disk.' FROM games WHERE igdb_id = 43631 ON CONFLICT (game_id, language_code) DO NOTHING;
