INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sub-command', 15627, '2001-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co42jw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkff.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sub Command', 'Take charge of the most deadly modern-day submarines in the world - three distinct submarines across two unique and challenging campaigns. Utilize cutting-edge sensor and weapon technology to locate, track and destroy the enemy - even deliver Tomahawk missiles to inland targets. Whether transiting, diving, or surfacing you control the smartest, stealthiest and most feared subs on the water today. Three submarines to command - Seawolf, 688(I) and Akula. Each contains authentic naval systems including Sonar, Radar and Target Motion Analysis. Test your skills while firing Tomahawk missiles, rescuing crippled subs, rising through the polar ice cap to communicate information and much more. Easy to use game interface - With straightforward controls and automated crewmen, controlling a submarine has never been easier. Enhanced sound and 3D graphics engine - 3D Objects (over 250), from Russian trawlers to France''s Mirage fighters - plus exacting sound modes pull you in like never before. You won''t just hear the torpedos, you will feel them.' FROM games WHERE igdb_id = 15627 ON CONFLICT (game_id, language_code) DO NOTHING;
