INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-jetz', 166206, '2001-10-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co72mx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccvju.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Jetz', 'A miniature crisis is happening and only you can stop it. Who or what could be trying to take over your home? Jump into your tiny, toy-size plane and fly missions of bravery to solve the mystery and save the day. Perfect your piloting skills as you dodge enemy fire, or command your fighter''s missile guidance system to lock-on and crush your opponent. Perform cool aerial stunts as you speed through Jetz''s realistic 3-D house. Fly at supersonic speeds using the turbo boost, then stun the enemy by hitting the air brake and stopping on a flying dime. Hot Wheels Jetz delivers big fun, colorful environments, and a hangar of zippy, toy-size planes. Choose from seven different aircraft, all based on original Hot Wheels Jetz designs. Buzz through eight challenging household environments from the living room to the bedroom and out into the garage. Monitor your hits, missiles, and more with onscreen displays. You''ll be asked to accept 10 missions, along with one bonus mission that must be completed to spare your home from certain doom.' FROM games WHERE igdb_id = 166206 ON CONFLICT (game_id, language_code) DO NOTHING;
