INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasy Star Online Ver. 2', 'The realm of Phantasy Star Online has increased. Phantasy Star Online Ver. 2 includes all of the original content, and expands the world with more levels, more features, and more evil to combat. Master the Ultimate Difficulty setting, survive the Challenge Dungeon, and reign as the champion of Battle Mode. The evolution of the original revolutionary gaming experience continues.' FROM games WHERE igdb_id = 45812 ON CONFLICT (game_id, language_code) DO NOTHING;
