INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquarePants: Operation Krabby Patty', 'Follow SpongeBob and his friends through the most sea-rrific adventures yet, including: Invasion of the Patty Snatchers, Boating School 101, and Hide N'' Go Jellyfishing. Adventure ensues as the Evil Plankton attempts to invade the Krusty Krab to steal Mr. Krab''s secret recipe for Krabby Patties. Play through four levels as SpongeBob SquarePants, Patrick Star, Sandy Cheeks, or Mr. Krab. Includes voiceovers by the SpongeBob SquarePants television actors and authentic music from the television show.' FROM games WHERE igdb_id = 2759 ON CONFLICT (game_id, language_code) DO NOTHING;
