INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam Federation vs. Zeon', 'When the imperiled Earth Federation battles the notorious Zeon Forces, which side will you be on? Mobile Suit Gundam: Federation vs. Zeon forces you to choose which army to lead in furious outer-space combat. Play more than 200 missions solo or share the screen with a friend for head-to-head or team battle action. Actual actors from the TV series provide full voice-overs in the game, immersing you in Mobile Suit Gundam world.' FROM games WHERE igdb_id = 43311 ON CONFLICT (game_id, language_code) DO NOTHING;
