INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barrel Patrol 3D', 'Barrel Patrol 3D is an arcade-style 3D shooter in which you protect fuel cells from enemy attackers inside circular arena levels. Gameplay mixes fast-paced shooting and defense across progressively harder waves, with simple controls and retro-style graphics.' FROM games WHERE igdb_id = 359705 ON CONFLICT (game_id, language_code) DO NOTHING;
