INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcanum-of-steamworks-and-magick-obscura', 255, '2001-08-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26ed.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xxm75p7feap3th2ump7m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcanum: of Steamworks and Magick Obscura', 'Imagine a place of wonder,where magic and technology hold equal sway, and an adventurer might just as easily wield a flintlock pistol as a flaming sword. A place where great industrial cities house castle keeps and factories, home to Dwarves, Humans, Orcs and Elves alike. A place of ancient runes and steamworks, of magic and machines, of sorcery and science. Arcanum is the first game to come from the development house Troika Games, LLC, started by former Fallout team members Tim Cain, Leonard Boyarsky, and Jason Anderson. This team takes the depth of gameplay and world-building in role-playing games to entirely new levels of realism and excitement. Arcanum creates a compelling new world where magic and technology coexist in an uneasy balance. As Arcanum opens, the mechanical age has only recently arrived in this ancient land where Humans, Elves, Dwarves, Orcs and other races have learned to survive in the new sprawling industrialized cities. But this radical shift from magic to technology has created a potentially explosive situation. As the townspeople and other thinkers begin mass production of light bulbs, batteries, eyeglasses and guns, the Mages grow leery. This tightly wound setting is the starting point from which the character must set out on his quest.' FROM games WHERE igdb_id = 255 ON CONFLICT (game_id, language_code) DO NOTHING;
