INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('legacy-of-kain-soul-reaver-2', 7893, '2001-10-31', 95, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93d6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar56zb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legacy of Kain: Soul Reaver 2', 'Soul Reaver 2 picks up where Legacy of Kain: Soul Reaver left off, with Raziel having just plunged through the Chronoplast time portal in his relentless pursuit of Kain. Over the course of his quest for revenge, Raziel must unearth the mysteries of Nosgoth’s ancient races, expose the machinations behind the corruption of the Pillars, and the vampire genocide. Throughout the game, Raziel acquires numerous new abilities, weapon enhancements, and spells, all of which are critical to the completion of his epic adventure. Soul Reaver is a third-person combat adventure filled with devious puzzles and kick-ass combat. Fly, swim, jump, and even travel from the material world to the spectral realm to overcome obstacles and conquer your enemies. With over 40 abilities to choose from, no two fights will ever be the same.' FROM games WHERE igdb_id = 7893 ON CONFLICT (game_id, language_code) DO NOTHING;
