INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-mummy-returns', 49961, '2001-05-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x5h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq6j6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mummy Returns', 'The popular film sequel to the equally popular original film now has its very own handheld video game. THE MUMMY RETURNS features elements of puzzle solving, hand-to-hand combat, first-person shooting, and flight simulation. Choose to play either the heroes or the villains, as you can take control of classic characters like the lovable Rock O''Connell or the wicked king of the zombies, Imhotep. With three playable characters in all, the game''s replay value is strikingly high. Boasting graphics that eclipse those of most handheld adventures, THE MUMMY RETURNS delivers all of the action and excitement from the film to the palm of your hand. You trek through countless Egyptian locales, battling spirits of the underworld, rats, pygmy mummies, scarabs, and much more. The most important thing is to keep your wits about you you wouldn''t want to become unraveled. Four modes provide hours of original gameplay.' FROM games WHERE igdb_id = 49961 ON CONFLICT (game_id, language_code) DO NOTHING;
