INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill 2: Restless Dreams', 'Silent Hill 2: Restless Dreams is an updated version of of Silent Hill 2. It contains all of the content of the original version and adds several pieces of new content. The most significant is a new short scenario called Born from a Wish, where players take control of Maria from her first moments right up to where she first appears in the main game. Also included is a sixth ending to the main scenario and a minor feature that allows the player to turn off the graphical effect, which makes the game look like it was shot on cheap film stock.' FROM games WHERE igdb_id = 22066 ON CONFLICT (game_id, language_code) DO NOTHING;
