INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Walker', 'A remake of the PC-98 game "Night Walker: Mayonaka no Tantei". This version uses the same source drawings as the original game, except with 256-color displays, and plays similarly. The characters are recolored, and match the anime more closely. (Shidō''s hair is purple, Guni''s body is green. Inexplicably, Yayoi''s hair is bubblegum pink.)' FROM games WHERE igdb_id = 256316 ON CONFLICT (game_id, language_code) DO NOTHING;
