INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-venus-starring-morning-musume', 338317, '2001-01-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sv8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw3jn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Venus starring Morning Musume.', 'Space Venus bills itself not as a game, but as "Music Visual Software". It takes the Japanese pop group Morning Musume and puts them in the role of the crew of a space station, charged with generating Life Oriented Virtual Energy (LOVE). The player chooses an area of the space station, where they''ll find different kinds of video experiences. Some areas simply play standard video clips, either taking place in the fictional space setting or showing behind-the-scenes footage from the making of this game. Some are special 360° panoramic videos where panning and zooming can be controlled with the gamepad. Some sections are more heavily interactive. One section, called simply "Mini-game", allows you to shoot at spaceships flying around the space station. Another section, "Morning Musume TVDJ", reuses the system from Sony''s earlier PS2 game TVDJ and allows the player to reedit and add effects to several of the group''s music videos in real-time. Failure to time placement of song sections appropriately results in repeating that part of the song before one progresses.' FROM games WHERE igdb_id = 338317 ON CONFLICT (game_id, language_code) DO NOTHING;
