INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kickboxing', 'Players choose one of 14 martial arts experts to lead to ultimate victory in this 3D fighting game from A1. Players can customize such details as fighting style, toughness, and even glove weight to find a fighter who matches their preferences. Guide your kickboxer from a rookie beginner to a contender for the heavyweight title. A two-player mode allows rivals to face-off in head-to-head bouts.' FROM games WHERE igdb_id = 76729 ON CONFLICT (game_id, language_code) DO NOTHING;
