INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('inu-no-osanpo', 169323, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3t6g.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inu no Osanpo', 'Players "walk" a virtual dog by walking on a treadmill and control the pet with a leash attached to a plastic dog in front of the player. Inu no Osanpo simulates the experience of walking a dog. Players first choose one of six breeds of dog to walk: Poodle, Pug, Pembroke Welsh Corgi, Shiba Inu, Labrador Retriever, or Siberian Husky. The difficulty of the game changes depending on the breed of dog chosen. After selecting a dog, the player selects one of three possible walking routes, each with a unique scenario. The goal of Inu no Osanpo is to maintain the dog''s happiness long enough to complete the entire route.' FROM games WHERE igdb_id = 169323 ON CONFLICT (game_id, language_code) DO NOTHING;
