INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triumph! War 2099', 'Triumph! WAR 2099 is a game of full-scale army vs army warfare. But this time man vs alien. Triumph! is a different than normal combat game, in the sense that your army does most of the grunt work. Instead of taking on the whole army single-handed, you must concentrate on gathering reinforcements, staying alive and taking on enemies in a more strategic method.' FROM games WHERE igdb_id = 350129 ON CONFLICT (game_id, language_code) DO NOTHING;
