INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy X', 'Final Fantasy X is the tenth main installment in the FF series and the first title released on sixth-generation consoles. It was also the first game to feature fully three-dimensional areas rather than including pre-rendered backdrops, and the first to include voice acting. Final Fantasy X tells the story of a star blitzball player, Tidus, who journeys with a young and beautiful summoner named Yuna on her quest to save the world of Spira from an endless cycle of destruction wrought by the colossal menace Sin.' FROM games WHERE igdb_id = 418 ON CONFLICT (game_id, language_code) DO NOTHING;
