INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gran-turismo-3-a-spec', 1600, '2001-04-28', 100, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xru.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8joi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo 3: A-Spec', 'More than two years in the making, Gran Turismo 3 A-spec features over 150 detailed cars -- each composed of more than 4,000 polygons -- 60 beginner, amateur and professional championship races, as well as ten endurance races and ten rally races. In addition to all-new special effects, such as sun glare, heat distortion and reflections, Gran Turismo 3 A-spec also offers up a soundtrack of more than 20 licensed tracks, and an even better replay mode with TV-style camera views. Two players can go head-to-head via split-screen and up to six can duke it out by linking multiple systems together via i.LINK. Released worldwide in 2001, Gran Turismo 3 a-Spec was designed by Polyphony Digital.' FROM games WHERE igdb_id = 1600 ON CONFLICT (game_id, language_code) DO NOTHING;
