INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocky & Rocky with Becky', 'An evil Hydra Dragon has been awakened from a long sleep and has unleashed the world''s most fearded mythical creatures on the land. It is up to you to stop them and eventually put an end to the evil Hydra''s madness! You can choose one of the three characters, Pocky, Rocky the Raccoon or Becky to embark on this fantastic and dangerous adventure. Collect magical items and a variety of power-ups to help battle the mythical bosses as you journey to the final showdown with the Hydra!' FROM games WHERE igdb_id = 1537 ON CONFLICT (game_id, language_code) DO NOTHING;
