INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Wants to Be a Millionaire: 3rd Edition', 'Who Wants To Be A Millionaire: 3rd Edition is the third game based on the successful TV show. Not surprisingly the game itself is unchanged with the exception of new questions. The player takes the role of a candidate and has to answer 15 questions by choosing the correct answer out of four given possibilities.' FROM games WHERE igdb_id = 43909 ON CONFLICT (game_id, language_code) DO NOTHING;
