INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kamen-rider-agito', 43864, '2001-12-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jz4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider Agito', 'A man named Shouichi Tsugami has lost his memories. He doesn''t know who he is, where he came from, or how he came upon his peculiar circumstances. Tsugami, seemingly for no reason, transforms into a powerful superhuman, Agito, whenever in the presence of the beings referred by the police as the "Unknown", a race of powerful monsters that have been causing murders around Tokyo, targeting certain people as their prey. In response, the police department unleash their newest weapon: the G3 powersuit, originally developed to fight against the "Unidentified Lifeforms", the enemies of No.4 (Kamen Rider Kuuga). G3 and Agito don''t know whether they should join up and defeat the Unknowns, their common enemy, or to combat each other, keeping the mysteries that entwine them separate. Ultimately, even more mysteries unfold, with the appearance of Kamen Rider Gills, who is on a search to uncover why his father committed suicide. These mysteries and others collide, as the true nature of Agito would ultimately determine the fate of humanity.' FROM games WHERE igdb_id = 43864 ON CONFLICT (game_id, language_code) DO NOTHING;
