INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 78: The Zero Yon', 'Simple 1500 Series vol. 78: The Zero Yon is a street racing game in which the player takes the role of a driver that wants to become the king of king in the street racing, and to do that he will have to compete against other drivers in the town and win the different races to get the best score and be the first one in the ranking. The player can also buy new parts for improve his car (like tires, engine, etc.).' FROM games WHERE igdb_id = 203072 ON CONFLICT (game_id, language_code) DO NOTHING;
