INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pool of Radiance: Ruins of Myth Drannor', 'The game is a dungeon crawl, with focus on hack and slash combat and exploration of large dungeons. Story progression and interaction with other characters is a minimal part of the game, although there is some interaction with NPCs and other in-game characters.' FROM games WHERE igdb_id = 5630 ON CONFLICT (game_id, language_code) DO NOTHING;
