INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tiny-toon-adventures-wacky-stackers', 6642, '2001-12-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d6y.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Toon Adventures: Wacky Stackers', 'What happens when you take classic puzzle gaming and toss in some of the most lovable characters in cartoon history? You get one undeniably awesome game. Buster Bunny, Plucky Duck, and the rest of the TINY TOONS crew are ready for fun, and you''re in the driver''s seat. The basic premise of this addicting, original title is to arrange pairs of colored eggs, dropping them onto the screen to create combinations. Of course, there are numerous obstacles and would-be detractors to make things more difficult (UFOs, Tasmanian Devils), and time is never on your side. There are plenty of characters from the animated series along for the adventure including Hampton J. Pig and Fifi La Fume and each is prepared for puzzle-style battle. As many as four players can link up to see who has the quickest reflexes, and there are plenty of single-player modes to keep you busy as well. If you''re a TINY TOONS fan, this one is a must-have. If you''re not a fan well, you should be.' FROM games WHERE igdb_id = 6642 ON CONFLICT (game_id, language_code) DO NOTHING;
