INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: Curse of the Sword', 'Tomb Raider: Curse of the Sword is a video game based on the Tomb Raider series. It is a sequel to the first Tomb Raider for the same system. You''ll experience the usual amounts of ledge jumping and rope climbing that one expects from a game in the Tomb Raider series, as well as a number of activities unique to this particular release, such as boss battles, demolitions, and submarine piloting.' FROM games WHERE igdb_id = 49993 ON CONFLICT (game_id, language_code) DO NOTHING;
