INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Street Fighter II Turbo: Revival', 'Capcom''s timeless Street Fighter masterpiece conquers the Game Boy Advance system. Choose from over 16 brawlers from the Street Fighter universe and execute special moves, and super combos to wreak havoc on your opponent and become the best street fighter in the world. Lightning fast animation, unbelievable graphics and Capcom''s signature gameplay make Super Street Fighter II Turbo the most respected fighting game of all time.' FROM games WHERE igdb_id = 45195 ON CONFLICT (game_id, language_code) DO NOTHING;
