INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Starfighter - Special Edition', 'The Special Edition of Star Wars Starfighter for Xbox features high-quality air and space combat, with added missions, a two-player mode, expanded racing and capture-the-flag play, and improved graphics. Set in the Star Wars universe and inspired by The Phantom Menace, players must save Naboo from the Trade Federation''s invasion. Players choose from three pilots, each with a unique ship: Rhys, a Naboo pilot-in-training with the N-1 starfighter; Vana, a Naboo expatriate with an ultra-fast, stealthy ship; and Nym, an alien pirate with a powerful, heavily armed starship.' FROM games WHERE igdb_id = 242773 ON CONFLICT (game_id, language_code) DO NOTHING;
