INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-wars-rogue-squadron-ii-rogue-leader', 4181, '2001-11-09', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9v76.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ny82tun6hwisa6wsmsqw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Rogue Squadron II - Rogue Leader', 'In Star Wars Rogue Squadron II: Rogue Leader you get the chance to jump into the cockpit of an X-wing and join Luke Skywalker and the Star Wars galaxy''s most daring pilots as they return to face off against the Empire. As in the original hit game for N64, you''ll relive favorite Star Wars battles including the perilous Death Star trench run, a daring space attack on a Star Destroyer and the legendary battle on the ice planet Hoth. Rogue Leader features stunning, movie like visuals and immerses players in an intense action-arcade experience. Aerial conflict takes place in a variety of craft such as the legendary X-wing, A-wing, and B-wing. For the first time, the game also features on-foot ground combat in missions directly based on or inspired by the original movie trilogy.' FROM games WHERE igdb_id = 4181 ON CONFLICT (game_id, language_code) DO NOTHING;
