INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-wars-super-bombad-racing', 18046, '2001-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co47v8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pmf8vtb6cv22jtbtmlom.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Super Bombad Racing', 'Jar Jar throws his Bongo racing ride into warp speed with his very own exciting big-headed kart racer Star Wars: Super Bombad Racing! Everybody from Star Wars Episode I: The Phantom Menace has put their intergalactic troubles aside to enter into a wild racing adventure -- Queen Amidala, Anakin, Yoda, Obi-Wan, Sebulba, Bos Nass, Sebulba, and even Darth Maul are all out for that checkered flag. Each racer gets to ride special racing vehicles (a Pod Racer, a Sith Interceptor, a Naboo Fighter), and with the different vehicles comes individually geared racing controls. Once the green light flashes, it’s a crazy dash for the finish across famous STAR WARS locations, with flying missiles and colorful power-ups blasting all over the map. Get mad air off jumps and crack open secret locations to find all of the game’s hidden special features. All this action explodes off the screen with incredible special effects and dazzling graphics from the force of the PlayStation 2 computer entertainment system. Meesa can’t wait to play this!' FROM games WHERE igdb_id = 18046 ON CONFLICT (game_id, language_code) DO NOTHING;
