INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park III: The DNA Factor', 'Jurassic Park III: The DNA Factor recreates the Jurassic Park world and takes players into an interactive pre-historic adventure. The game is a fun and unique mix of side-scrolling adventure stages and intense puzzle action. Jurassic Park III: The DNA Factor includes more than 10 species of dinosaurs and 12 huge levels to explore.' FROM games WHERE igdb_id = 6481 ON CONFLICT (game_id, language_code) DO NOTHING;
