INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Sorcerer''s Stone', 'Harry Potter and the Sorcerer''s Stone is the first Harry Potter video game for the PlayStation, and one of several different games based on the book and movie. This version is a three-dimensional action adventure, where Harry must complete a number of challenges in order to pass his first year of studies at Hogwarts School of Witchcraft and Wizardry. Successful completion of the tasks often results in house points for Harry''s house Gryffindor and failure in some deducts points, so the race for the House Cup can stay open until the end.' FROM games WHERE igdb_id = 341 ON CONFLICT (game_id, language_code) DO NOTHING;
