INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anachronox', 'Welcome to Anachronox, an abandoned alien artificial planet at the centre of the universe, now home to lowlifes, thieves, and scoundrels. Here we join Sylvester "Sly Boots" Bucelli--a down on his luck PI--and a cast of 6 other unlikely heroes on their quest to discover who or what is trying to destroy the universe. They are the only ones that believe it is happening, and the only ones that can do something about it.' FROM games WHERE igdb_id = 5622 ON CONFLICT (game_id, language_code) DO NOTHING;
