INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: The Final Scene', 'Search a Darkened Movie Theater to Free a Hostage from her Captor’s Dangerous Plot! When a high school friend gets kidnapped in a historic theater, you, as Nancy Drew, are plunged into a desperate race against the clock. With the theater being torn down in just three days, can Nancy outwit the kidnapper and rescue her friend before the wrecking ball flies? Or will this be Maya’s final scene?' FROM games WHERE igdb_id = 7624 ON CONFLICT (game_id, language_code) DO NOTHING;
