INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Rumble Arena', 'Digimon Rumble Arena is a crossover fighting video game developed and published by Bandai in association with Hudson Soft for the PlayStation video game console. Players are able to choose from up to 24 characters (fifteen of which need to be unlocked) from the Digimon Adventure and Digimon Tamers seasons of the Digimon anime, such as Terriermon, Agumon, Gatomon, and Renamon.' FROM games WHERE igdb_id = 4133 ON CONFLICT (game_id, language_code) DO NOTHING;
