INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario & Luigi', 'Mario & Luigi is an unofficial DOS remake of Super Mario Bros. Just like in the original game, it features Mario the plumber, jumping around, collecting pickups and defeating enemies across Mushroom Kingdom. Mario can find a mushroom which makes him grow, and a fire flower that allows him to shoot fireballs.' FROM games WHERE igdb_id = 117772 ON CONFLICT (game_id, language_code) DO NOTHING;
