INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myst III: Exile', 'MYST III: EXILE introduces a new villain Saavedro, who seeks revenge when he finds out his homeland was destroyed by Atrus'' sons. The player must track the villain through several surrealistic Ages, navigating puzzles to uncover the truth behind this new adversary. Only then can disaster be averted to choose who was right and who was wrong. Saavedro is played by Academy Award nominee Brad Dourif (One Flew Over the Cuckoo''s Nest).' FROM games WHERE igdb_id = 797 ON CONFLICT (game_id, language_code) DO NOTHING;
