INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('serious-sam-the-first-encounter', 857, '2001-03-21', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nlk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ttg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Serious Sam: The First Encounter', 'A first person shooter extravaganza where you take the role of Serious Sam, a badass killer whose goal is to defeat monsters commanded by Mental, an extraterrestrial entity that wants to destroy humanity. Serious Sam is a high-adrenaline arcade-action shooter heavily focused on frantic arcade-style single player action. In a world where cyberpunk meets fantasy-fiction and advanced technology is mixed with black magic and psycho-powers, Sam travels through the beautiful world of ancient Egypt and several diverse planets, confronting countless Mental''s minions on his way to the Mental''s base.Key Features Frantic Arcade-Style Action - Fight your way through 15+ nightmarish warriors in Mental''s army, including the charging Sirian Werebull, screaming Headless Kamikaze and other crazy monsters, and finally challenge the multi-story Ugh-Zan boss!' FROM games WHERE igdb_id = 857 ON CONFLICT (game_id, language_code) DO NOTHING;
