INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bejeweled', 'Bejeweled is a tile-matching puzzle video game by PopCap Games, first developed for browsers in 2001. Three follow-ups to this game have been released. More than 75 million copies of Bejeweled have been sold, and the game has been downloaded more than 150 million times. Although the game is no longer downloadable through PopCap''s website, the installer can be downloaded via the Wayback Machine.' FROM games WHERE igdb_id = 8318 ON CONFLICT (game_id, language_code) DO NOTHING;
