INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Gotham Racing', 'Project Gotham Racing (PGR) is a racing game, the first in its series, developed by Bizarre Creations and published by Microsoft for the Xbox gaming console. The first title in the franchise, Project Gotham Racing, is an Xbox launch title that quickly became the second best-selling game for the console after Halo: Combat Evolved. PGR is a spiritual successor to the Sega Dreamcast game Metropolis Street Racer after Sega discontinued the hardware business and became a software based company. PGR is as of July 12, 2010 compatible with the Xbox 360 through a downloadable update.' FROM games WHERE igdb_id = 3320 ON CONFLICT (game_id, language_code) DO NOTHING;
