INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi no Dungeon: Fuurai no Shiren GB2 - Sabaku no Majou', 'Shiren the Wanderer GB2: Magic Castle of the Desert is a roguelike role-playing video game developed by Chunsoft. It is part of the Mystery Dungeon series, and is a sequel to Shiren the Wanderer GB: Moonlight Village Monster. It was originally released for the Game Boy Color by Chunsoft in 2001. A Nintendo DS remake was released by Sega later in 2008.' FROM games WHERE igdb_id = 85949 ON CONFLICT (game_id, language_code) DO NOTHING;
