INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man: Mysterio''s Menace', 'Set in New York, Spider-Man: Mysterio''s Menace enables players to assume the role of Spider-Man as they take on super-villain Mysterio and his illusory tricks for control of Manhattan. Spider-Man must fight a slew of Mysterio''s sinister conspirators and gadgetry to get to the bottom of their plot and free New York from Mysterio''s mind-warping grip.' FROM games WHERE igdb_id = 6605 ON CONFLICT (game_id, language_code) DO NOTHING;
