INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man 2: The Sinister Six', 'Spider-Man 2: The Sinister Six (or Spider-Man 2: Enter the Sinister Six in Europe) is a 2001 platform video game based on the Marvel Comics character Spider-Man. It was developed by Torus Games and published by Activision for the Game Boy Color. It is an alternative sequel to Spider-Man (2000) and mostly follows the events of the Game Boy Color version of that game. Though it has a similar format, it is not related to Spider-Man: Return of the Sinister Six (1992).' FROM games WHERE igdb_id = 49971 ON CONFLICT (game_id, language_code) DO NOTHING;
