INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution 5thMix', 'Dance Dance Revolution 5thMIX, or DDR 5th Mix, is the 5th game in the Dance Dance Revolution series of music video games. It was released to the arcades by Konami on March 27, 2001. Although only officially released in Japan, units exist worldwide. DDR 5th Mix contains a total of 122 songs, nine of which are hidden and unlockable. Of those songs, 40 of them (including all nine unlockable songs) are brand new to Dance Dance Revolution.' FROM games WHERE igdb_id = 3678 ON CONFLICT (game_id, language_code) DO NOTHING;
