INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropico', 'As the newly instated dictator of an obscure Caribbean Island, you will build a path of progress for your sapling nation, overcoming poverty, strife and other evils. Combining building-oriented gameplay with a healthy dose of Latin American political intrigue - Tropico bundles it all up in a fun, totally original and utterly addictive package.' FROM games WHERE igdb_id = 274 ON CONFLICT (game_id, language_code) DO NOTHING;
