INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey Ball', 'Monkey Ball is a 2001 platform/party video game developed by Amusement Vision and published by Sega. The game debuted in Japan at the 2001 Amusement Operators Union trade show as Monkey Ball, an arcade cabinet running on Sega''s NAOMI hardware and controlled with a distinctive banana-shaped analog stick.' FROM games WHERE igdb_id = 40105 ON CONFLICT (game_id, language_code) DO NOTHING;
