INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Watchmaker', 'The Watchmaker is a real-time 3D adventure of mystery and magic. Lawyer Victoria Conroy and paranormal expert Darrel Boone are charged with the mission of recovering a magical, pendulum-shaped device that has fallen into the hands of a religious cult. Within 24 hours, the pendulum''s power will become great enough to threaten the world, and Conroy and Boone must unravel the secrets of a strange castle to find the device and prevent catastrophe. The player has complete control of both characters who must work in tandem to investigate their surroundings and solve puzzles. The player can also toggle between third- and first-person perspectives.' FROM games WHERE igdb_id = 82091 ON CONFLICT (game_id, language_code) DO NOTHING;
