INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scorched 3D', 'Scorched 3D is a turn-based artillery game modeled after the classic DOS game Scorched Earth "The Mother Of All Games". Unlike Scorched Earth however, it is available free in its entirety. Also, Scorched 3D adds, amongst other new features, a 3D island environment and LAN and internet play. Scorched 3D is an open source game for both Microsoft Windows and Unix-like (Linux, FreeBSD, Mac OS X, Solaris, etc.) operating systems.' FROM games WHERE igdb_id = 51249 ON CONFLICT (game_id, language_code) DO NOTHING;
