INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park III: Dino Defender', 'Jurassic Park III: Dino Defender is a game based on the Jurassic Park 3 franchise. You play a Dino Defender who must travel to Isla Sorna to capture the dinosaurs after a freak storm has knocked out the power supply and freed them. Your role is to use whatever is available to capture the dinosaurs, and discover what has happened. The game plays as a side scrolling platform action game, with the player fighting a range of dinosaurs.' FROM games WHERE igdb_id = 74091 ON CONFLICT (game_id, language_code) DO NOTHING;
