INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exhibition of Speed', 'Looking for high-speed authentic arcade action? Strap yourself firmly in for this electrifying new racing game. Extensive game features include over twenty world-class racing vehicles including hidden cars, fifteen challenging tracks with varying weather conditions in five different universes, spectacular car jumps with additional boosters on the track, stunning visual SFX on the landscapes and multiplayer gaming for up to four players.' FROM games WHERE igdb_id = 46365 ON CONFLICT (game_id, language_code) DO NOTHING;
