INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero Comico', 'Zero Comico is an Italian video game featuring three famous Italian comedians: Aldo Giovanni and Giacomo as the main characters. The player is in control of all three characters as they try to free the world from an evil force that has taken control over mankind through television. The game features a variety of puzzles with a comedy theme.' FROM games WHERE igdb_id = 185970 ON CONFLICT (game_id, language_code) DO NOTHING;
