INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Racer', 'Toy Racer is a racing game that''s an extension of Toy Commander racing sections, designed exclusively for both offline and online multiplayer modes for up to four players. As a result, there is no possibility to play against AI controlled players, being the only single player features of the game both a Practice and a Time Attack modes.' FROM games WHERE igdb_id = 46369 ON CONFLICT (game_id, language_code) DO NOTHING;
