INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cart Fury', 'Cart Fury is a 2000 open wheel-themed racing video game developed by Midway Games based on Championship Auto Racing Teams (CART). Originally released to arcades, a version was also released for the PlayStation 2. Some of its famous drivers like Juan Pablo Montoya, Michael Andretti and Christian Fittipaldi (Brazil) are included in the game. The game features the voice of Danny Sullivan. Licensed music by Disturbed and Outkast are used as the official soundtrack of this game.' FROM games WHERE igdb_id = 43275 ON CONFLICT (game_id, language_code) DO NOTHING;
