INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Star Pro Wrestling II', 'For many wrestling, the desire to see "Misawa (NOAH) vs Mutoh (NJPW)", "Akiyama (NOAH) vs Nagata (NJPW)" or "Hashimoto (ZERONE) vs Kobashi (NOAH)" was all but a distant dream that goes beyond the framework of the organization fixtures. But this is the reality in the ring of "ASPW2"! No longer is there walls between the organization, the time to fight is now!' FROM games WHERE igdb_id = 43619 ON CONFLICT (game_id, language_code) DO NOTHING;
