INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Windsurfers Paradise', 'Windsurfers Paradise is a video game available, on PlayStation, of sport genre, developed by Theyer Gfx and published by Midas Interactive Entertainment. Sail over the waves of four of the world''s most beautiful beaches. It''s down to you to master your own lightweight windsurfer, before you dive in to challenge the computer or your friends in a competition to see who can execute the perfect stunt, or jump the highest wave. You will have to be able to read the wind if you want to succeed. In Windsurfers Paradise only losers fall off!' FROM games WHERE igdb_id = 12902 ON CONFLICT (game_id, language_code) DO NOTHING;
