INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinniku Banzuke GB 3: Shinseiki Survival Retsuden!', 'The third in the GB series! The software is exclusively for GBC, and the graphics are more realistic and upgraded. Equipped with "SASUKE2000" that was aired as a special in the fall of 2000. Of course, there are also hidden competitions that are popular in the series, such as "Service Ace," "Power Force," "Super Shot," "Spray Hitter," and "Struck Out Bingo." Including the familiar Kane Kosugi, unique original players only for the game have also appeared! There are plenty of competitions where friends can play against each other with communication cable support, and new rules will expand the play.' FROM games WHERE igdb_id = 281657 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 281657 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
