INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry Summoner', 'This spin-off entry in the Wizardry series has the player’s party searching for a forbidden book of ancient power for the king through various randomly generated dungeons. New to the series is the Summoner class, which can capture and summon creatures encountered in the labyrinths. Otherwise, gameplay follows the series’ traditional template: create a party in the sole town, explore maze-like dungeons, and fight in turn-based battles. A planned North American release was later cancelled.' FROM games WHERE igdb_id = 60870 ON CONFLICT (game_id, language_code) DO NOTHING;
