INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Columns Crown', 'Princess Dazzle has searched all over for the missing Magic Gems that fill in the Columns Crown. You must help her recover them from a band of Forest Thieves by beating every puzzle to unlock the hidden Gems! Can you collect them all and complete the crown? Frantic multi-player action full of devastating special moves. Collect Magic Gems to unleash spectacular elemental attacks. New Survival, Versus, and Flash Columns modes.' FROM games WHERE igdb_id = 6350 ON CONFLICT (game_id, language_code) DO NOTHING;
