INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konchuu Hakase 3', 'A game that focuses on "the fun of finding and catching insects" by collecting insects that live in mountains and rivers in various ways. Take on the challenge of collecting insects by making full use of various actions such as crouching, dashing, catching hats, and catching directly above! Collected insects can be bred at home or exhibited at fairs. Insects that have been successfully bred will be recorded in the picture book. You can exchange insects with your friends by using a communication cable.' FROM games WHERE igdb_id = 281699 ON CONFLICT (game_id, language_code) DO NOTHING;
