INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gear Senshi Dendoh', 'A combination of 2D sprite-base action game and a 3D polygonal versus fighting game. The main gameplay has you controlling a giant Gundam-like robot, crashing every enemy unit in your path. After beating a stage boss character, the game switches into a 3D one-on-one fighter game. This mix of styles really sets it apart as a unique game.' FROM games WHERE igdb_id = 19595 ON CONFLICT (game_id, language_code) DO NOTHING;
