INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Herohero-kun', 'Herohero-kun is a role-playing game for Game Boy Color released by Imagineer in 2001. It is based on the manga "Herohero-kun," but the main character is not Herohero but the original game''s main character. The main character''s name can be up to four characters, and the gender can also be selected. The purpose is to rescue the townspeople of Ukiuki who were put to sleep by Suyasuya.' FROM games WHERE igdb_id = 209906 ON CONFLICT (game_id, language_code) DO NOTHING;
