INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road to India: Between Hell and Nirvana', 'Road to India is an adventure video game in which the player assumes the role of an American student named Fred Reynolds, who has travelled to India to find his girlfriend, Anusha, who was kidnapped by thugs. In the game the player has only three days to find the girlfriend, where they visit places such as New Delhi and the Taj Mahal. Each day is broken up into two parts: reality and the dream.' FROM games WHERE igdb_id = 12473 ON CONFLICT (game_id, language_code) DO NOTHING;
