INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Football 2002', 'Backyard Football 2002 was developed by Humongous Entertainment and published by Infogrames in 2001 for Windows and Macintosh. In this game, one can play as their favorite National Football League stars as kids. The goal of the game is to lead a team to Cereal Bowl glory. Updated versions of the game were published yearly on various platforms through Backyard Football 2006.' FROM games WHERE igdb_id = 50902 ON CONFLICT (game_id, language_code) DO NOTHING;
