INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-14 Tomcat', 'F-14 Tomcat is a port of Absolute Entertainment''s 1994 SNES game Turn and Burn: No-Fly Zone with some GBA exclusive content. It features a multiplayer mode between other systems and a brand new storyline: the player controls a F-14 pilot chosen by the US government to be assigned in the theater of operations of a war between the republics of China and Taiwan to protect America''s "interests" in the region.' FROM games WHERE igdb_id = 259334 ON CONFLICT (game_id, language_code) DO NOTHING;
