INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX 2002 Featuring Ricky Carmichael', 'Get your moto kicks on the newest, most advanced hand held system. Prepare for new levels of immersion, authenticity and compelling gameplay with MX 2002 featuring Ricky Carmichael. Featuring more than 20 of the most death defying tricks, 30 pro riders and fast intense competition, MX 2002 featuring Ricky Carmichael is a perfect blend of traditional racing and free ride madness. This isn''t just a game - it''s a complete motocross experience!' FROM games WHERE igdb_id = 18265 ON CONFLICT (game_id, language_code) DO NOTHING;
