INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Alon D''ar', 'The Legend of Alon D''ar is a role-playing video game. The game plays somewhat like the Final Fantasy series'' Active Time Battle, with the player having to wait certain time for their turn. The game features a vast world to explore; there are several towns and a variety of monsters to combat. The game also features multi-player experience after unlocking the second character in the story.' FROM games WHERE igdb_id = 19420 ON CONFLICT (game_id, language_code) DO NOTHING;
