INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xin Shen Diao Xia Lu Zhi Wanjie Pian', 'Xin Shen Diao Xia Lu Zhi Wanjie Pian is the second installment in the series based on Louis Cha''s (better known by his pen name Jin Yong) The Return of the Condor Heroes. Players will control Yang Guo who finds out that his lover Xiaolongnü is still alive after 16 years and sets out to find her. The game plays like an RPG. Players move Yang Guo using the mouse and battles use a turn-based system where each character out of a party of up to 3 characters can attack as soon as their meter is full.' FROM games WHERE igdb_id = 295240 ON CONFLICT (game_id, language_code) DO NOTHING;
