INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perfect! Pool', 'Perfect! Pool is a basic traditional pool simulator, with advanced controls and realistic graphics. With a very advanced and easy-to-use 3D camera, the game is made simple and clear. The player can control the intensity of his shot as well as induce a spin on the cue ball to produce his desired effects. You can challenge friends by choosing the 2-player option, in which opponents can face each other turn by turn on the same computer as well as over a network.' FROM games WHERE igdb_id = 93181 ON CONFLICT (game_id, language_code) DO NOTHING;
