INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The 3D Gamemaker', 'Unleash your imagination... Now anyone can build their ideal game in seconds. With just one click of a mouse, you can create a uniquely playable game without needing any programming knowledge or artistic skills at all. Offering over 12 billion gaming options. The 3D Gamemaker opens up a whole concept in gaming, providing fun for all the family.' FROM games WHERE igdb_id = 270689 ON CONFLICT (game_id, language_code) DO NOTHING;
