INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armagetron Advanced', 'Armagetron is a multiplayer game in 3d that attempts to emulate and expand on the lightcycle sequence from the movie Tron. It''s an old school arcade game slung into the 21st century. Highlights include a customizable playing arena, HUD, unique graphics, and AI bots. For the more advanced player there are new game modes and a wide variety of physics settings to tweak as well. It is available for Linux, Mac OS X, Microsoft Windows, AmigaOS 4 and OpenBSD as free software released under version 2 of the GNU General Public License.' FROM games WHERE igdb_id = 51244 ON CONFLICT (game_id, language_code) DO NOTHING;
