INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sail Simulator 4', 'Sail Simulator 4 gives you the change to recreate thrill of sailing on your PC: Choose from seven prestigious boats, sail on the famous Isle D''Ouessant in France and Vierwaldstätter Sea in Switzerland. Learn the basics, master the instruments, configure the sailing conditions and set sail... It''s you versus the elements!' FROM games WHERE igdb_id = 143740 ON CONFLICT (game_id, language_code) DO NOTHING;
