INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.League Jikkyou Winning Eleven 2001', 'J.League Jikkyō Winning Eleven 2001 (known as World Soccer Winning Eleven 4) is a sports video game developed by Konami for the PlayStation exclusively in Japan in June 2001. It is an addition to the Winning Eleven J-League series, and the successor to the J.League Winning Eleven 2000. The game only features club teams (no national teams) and teams from both tiers of the J. League totalling 28 teams. The game also features seven foreign teams from the European football leagues. The game uses the Winning Eleven 2000 engine.' FROM games WHERE igdb_id = 181572 ON CONFLICT (game_id, language_code) DO NOTHING;
