INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Mir 2', 'The Legend of Mir 2 (Korean: 미르의 전설 2) is a sprite-based isometric 3-D massively multiplayer online role-playing game developed by Korean-based WeMade Entertainment' FROM games WHERE igdb_id = 51204 ON CONFLICT (game_id, language_code) DO NOTHING;
