INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angelic Concert', 'You''re a DJ, if DJ''s existed in the medieval magical setting that the story is based on, who happen to be the ''music'' behind the voice of the main character. Now, her aim in life is to aim higher in her musical career by entering the Angelic Concert. The winner receives fame, fortune and adventure on the short but well-drawn way to the concert. The game mixes AVG-style text with musical minigames.' FROM games WHERE igdb_id = 69152 ON CONFLICT (game_id, language_code) DO NOTHING;
