INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konami Krazy Racers', 'Race your favorite Konami characters through 16 action packed, fun-filled courses on your way to the checkered flag! 16 challenging courses showcase the power of Game Boy Advance graphics, including Cyber Field, Ice Paradise, Pop ''n Beach, Skybridge, and many more! 8 Classic Konami characters to choose from, including Ninja from Metal Gear Solid, Dracula of Castlevania fame, and Goemon the Mystical Ninja.' FROM games WHERE igdb_id = 6495 ON CONFLICT (game_id, language_code) DO NOTHING;
