INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V.G. Re-birth', 'A visual novel game in which the player plays the part of a reporter working on a story about the V.G. competition. The game also introduces the new character Sakuragi Hiyori. Depending on the choices the player makes, he/she will be paired with Yuka, Tamao or Reimi. V.G. Rebirth Dash: An update to V.G. Rebirth which includes nearly every other non-boss character (Yuuki Ayako is absent as she is a lesbian) as an option to pair with the player. It also introduces the new character Hatano Keiko.' FROM games WHERE igdb_id = 180273 ON CONFLICT (game_id, language_code) DO NOTHING;
