INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knights of the Cross', 'Based on the Polish novel by Henryk Sienkiewicz. It''s a turn-based strategy game where players take on the role of a knight of either side and must engage in a series of tactical missions, manoeuvring your forces and defeating your enemies in typical fashion. There are over 100 battles to take part in, with new units, weapons and upgrades available as you complete each one, while environmental conditions such as rain, snow and storms have an impact on the battles' FROM games WHERE igdb_id = 50474 ON CONFLICT (game_id, language_code) DO NOTHING;
