INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 2002', '2002''s version of Microsoft''s long running series of non-combat, commercial flight simulators. The game uses a completely new 3D graphics engine which features photorealistic terrain as well as some nifty effects like jet contrails, volumetric clouds and a completely 3D virtual cockpit for each of the 12 planes in the game (which include the new Cessna 208 Caravan Floatplane and Boeing 747-400).' FROM games WHERE igdb_id = 73734 ON CONFLICT (game_id, language_code) DO NOTHING;
