INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Rainbow Six: Rogue Spear - Black Thorn', '9 new single-player missions wrapped in a thrilling new story; 6 new multiplayer- only maps including new locations and new versions of your old favourites; 14 new weapons including the m60 machine gun and the futuristic p90; an all new Lone Wolf multiplayer mode one heavily armed operative takes on all the rest! The winner of the first round becomes the Lone Wolf in the next; all the classic game types from Roque Spear: defend , terrorist hunt, assault, recon and more.' FROM games WHERE igdb_id = 1846 ON CONFLICT (game_id, language_code) DO NOTHING;
