INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caxy Gambá Encontra o Monstruário', 'Caxy Gambá Encontra o Monstruário is a point-and-click adventure game that tells the story of Caxy Gambá, a marsupial who, during a stormy night, takes shelter in a mansion in the middle of nowhere. It was produced by 44 Bico Largo, idealized by Ale McHaddo, and had the special participation of José Mojica Marins, playing his trash horror film character Coffin Joe.' FROM games WHERE igdb_id = 257103 ON CONFLICT (game_id, language_code) DO NOTHING;
