INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carrera: Grand Prix', 'Carrera Racing is a racing game based on the famous toy. Like in the original the player only has to control the speed and change lanes, there is no steering involved. Depending on the chosen mode - arcade or classic - changing lanes is only possible at certain parts of the course. Bonus fields give additional effects, e.g. more or less speed.' FROM games WHERE igdb_id = 146607 ON CONFLICT (game_id, language_code) DO NOTHING;
