INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giga Wing 2', 'Giga Wing 2 (ギガウイング2?) is a 2000 vertical scrolling shooter arcade game developed by Takumi and published by Capcom on Sega''s NAOMI arcade system board and later ported in 2001 to the Dreamcast console. The arcade version is notable both for its excessive scores (scores in the quintillions are not unheard of), and for using a horizontally aligned monitor (much like Treasure Co. Ltd''s Radiant Silvergun), something that is considered rare for a vertical shooter.' FROM games WHERE igdb_id = 9163 ON CONFLICT (game_id, language_code) DO NOTHING;
