INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarCommander', 'Conventionally styled 2D real-time strategy is set during the June 1944 D-day Allied invasion at Normandy. Players take command of an American infantry unit right in the thick of it all, to guide them through two historically based campaigns of 12 missions each. Factors such as 11 different character classes, several available buildings and fortifications, a day-and-night cycle, and changing weather conditions are designed to bring variety and challenge to the WWII-themed game' FROM games WHERE igdb_id = 204564 ON CONFLICT (game_id, language_code) DO NOTHING;
