INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anstoß Action', 'With Anstoss Action, a football simulation followed in 2001, the data of which can be integrated into Anstoss 3 to Anstoss 3 Action or A3 Action for short (comparable to EA Sports'' “Football Fusion” technology). However, Anstoss Action could not really prevail against the competition from Electronic Arts and caused Ascaron''s financial difficulties due to high development costs, which culminated in the first bankruptcy.' FROM games WHERE igdb_id = 98963 ON CONFLICT (game_id, language_code) DO NOTHING;
