INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superlite-1500-series-slither-link', 216562, '2001-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob4t0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sciqw8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperLite 1500 Series: Slither Link', 'Slitherlink (also known as Fences, Takegaki, Loop the Loop, Loopy, Ouroboros, Suriza and Dotty Dilemma) is a logic puzzle developed by publisher Nikoli. Slitherlink is played on a rectangular lattice of dots. Some of the squares formed by the dots have numbers inside them. The objective is to connect horizontally and vertically adjacent dots so that the lines form a simple loop with no loose ends. In addition, the number inside a square represents how many of its four sides are segments in the loop. Other types of planar graphs can be used in lieu of the standard grid, with varying numbers of edges per vertex or vertices per polygon. These patterns include snowflake, Penrose, Laves and Altair tilings. These add complexity by varying the number of possible paths from an intersection, and/or the number of sides to each polygon; but similar rules apply to their solution. SuperLite 1500 Series - Slither Link is a puzzle game based on the Slitherlink logic puzzle featuring over 200 different stages.' FROM games WHERE igdb_id = 216562 ON CONFLICT (game_id, language_code) DO NOTHING;
