INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinder Pingui: Fresh Adventures', 'Fresh Adventures is a 2001 collection of 4 advergames all themed around the Kinder product line, developed by Ubisoft GmbH and Ferrero Germany. Released in Germany, Austria and Italy (as far as we are aware), the player takes control of "Pingui" and "Milchschnitte" and must venture forth and defeat the 4 villains of the game. The game is seperated into 4 sub-games: Der finsteres Dschungle (English: The Dark jungle) Das magische Tal (English: The Magical Valley) Der geheimnisvolle Berg (English: The Mysterious Mountain) Die Weltraumfabrik (English: The Space Factory)' FROM games WHERE igdb_id = 186416 ON CONFLICT (game_id, language_code) DO NOTHING;
