INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vectopia', 46514, '2001-02-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vectopia', 'Unlike the previous Vecmania, which comprised seven full games and two demos, the majority of Vectopia is composed of unfinished demos and only three full games.  In order to cycle through the games, once the menu screen appears after power-up, the player must press button one on the Vectrex controller, then to play a game they must press button four  Games in Vectopia:  - Wormhole  - Trakkers  - Vectropolis 500 (demo)  - Spike''s Water Balloons  - Control Test (demo)  - Mad Planetoid Test Wk (demo)  - Star Fire Early Work (demo)  - Star Fire Early Work II (demo)  - Star Fury Test Work  - Trivia' FROM games WHERE igdb_id = 46514 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 46514 AND p.igdb_id = 70 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman-online', 6716, '2001-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30fo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm7fs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman Online', 'Just when you thought Bomberman had planted his last explosive, the prolific video game hero returns for a modern update on his classic series. With addictive battles, frantic new modes, and brand new stages, Bomberman Online offers explosive action for all. Fans of the older multiplayer versions of the franchise will rejoice at the inclusion of four online modes Battle Royal, Hyper Bomber, Panel Attack, and Submarine Attack each designed to accommodate up to 10 players. The game''s lone single-player mode boasts five awesome levels, and the graphics are rendered in 3D this time around.' FROM games WHERE igdb_id = 6716 ON CONFLICT (game_id, language_code) DO NOTHING;
