INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 2002: Professional Edition', 'This is a special edition of Microsoft Flight Simulator 2002 and includes the following additional features: - Two new aircraft, the Cessna 208 Grand Caravan and the Rayethon BE58 Baron. - A Flight Instructor''s Station which allows a pilot to monitor and interact with students while they fly. - An editor that can be used to create new buildings and aircraft or to alter the flight physics of existing planes.' FROM games WHERE igdb_id = 711 ON CONFLICT (game_id, language_code) DO NOTHING;
