INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SNK vs. Capcom: Card Fighters 2 - Expand Edition', 'The Japan only sequel to SNK vs. Capcom Card Fighters'' Clash adds over 120 new cards, featuring many new characters, 40 cards of a new type called "Reaction cards" have also been added. Unlike the first game, SNK vs. Capcom - Card Fighters 2 - Expand Edition released as a single game, allowing players to choose to start with either an SNK or Capcom deck.' FROM games WHERE igdb_id = 75441 ON CONFLICT (game_id, language_code) DO NOTHING;
