INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsugunai: Atonement', 'Tsugunai is the story of Reise, a warrior who has inadvertently angered the Goddess of Light by stealing the mystical Treasure Orb. As punishment, the Goddess of Light forever separates his soul from his body unless he atones for his sins by helping the people of Walondia. Without a physical body of his own, the only way to change the fates of the people is to possess them.' FROM games WHERE igdb_id = 43606 ON CONFLICT (game_id, language_code) DO NOTHING;
