INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('city-crisis', 22011, '2001-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30ha.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sct056.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Crisis', 'Your mission is to save helpless people from crime and disaster in a city in turmoil. Three action packed game modes let you pilot one of five rescue choppers through a modern city in crisis, performing daring roof top rescues, extinguishing high-rise infernos and apprehending fugitives on the run. A turbulent city is under siege from disasters, and the only way to save the day is to get in from the air. So set those rotors spinning and take off to take on City Crisis. As a skilled chopper pilot, you''ll fly one of three real-life rescue and pursuit helicopters through a bustling city, zigzagging through high-rise buildings and weaving around dangerous electrical wires. Missions will have you saving citizens from the rooftops from certain death in Rescue mode, performing daring rooftop cable jumps to nab citizens and their pets from natural disasters. Then combat towering infernos from the air with water cannons and fire-extinguishing missiles, always on the yoke to keep control against unexpected updrafts and sudden explosions. Finally, whisk through the high-rise buildings at top speed in a risky pursuit of criminals on the run and help bring justice to this city in crisis. The fate of the people and the future of the city is in your hands!' FROM games WHERE igdb_id = 22011 ON CONFLICT (game_id, language_code) DO NOTHING;
