INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'When Tails Gets Bored', 'When Tails gets Bored is a fangame that was created in the website Sonic Vegemite. The player controls just as Sonic plays in the Mega Drive titles. Sonic must find the Special Stages to gain knowledge about why tails is bored. Beat 4 special stages to get the true ending. Besides that, the player must traverse through 9 zones (2 secret) and complete whatever hoax Estel has in store for him.' FROM games WHERE igdb_id = 228460 ON CONFLICT (game_id, language_code) DO NOTHING;
