INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Hello Kitty Vol. 04: Trump', 'Simple 1500 Series Hello Kitty Vol. 04: Trump is a Hello Kitty themed card game for the PlayStation. Trump or trumps or trump suit are terms used in trick-taking games, traditionally called whist-style games although the best-known example may now be bridge, where cards of one suit rank above all non-trump cards, and automatically prevail over them, losing only to a higher trump if one is played to the same trick.' FROM games WHERE igdb_id = 64650 ON CONFLICT (game_id, language_code) DO NOTHING;
