INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sítio do Picapau Amarelo: Emília e a Reforma da Natureza', 'The Reforma da Natureza CD-ROM had as its theme a computer brought by the Viscount to Sítio de Dona Benta. Emília uses make-believe and the computer to carry out renovations in nature. All the renovations that appear in the book appear in the game at some point: the edible book, the bird''s nest, the renovation of the mocha cow, among others. The highlight is the games that Emília uses to undo the renovation.' FROM games WHERE igdb_id = 286929 ON CONFLICT (game_id, language_code) DO NOTHING;
