INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL 2K2', 'NFL 2K2 is a complete football simulation, giving you a variety of ways to play. You can compete in a single exhibition game, start up a franchise, or move directly to the playoffs. NFL 2K2 uses a TV-style presentation, featuring telestration, action replays, sideline animations, stadium lighting and a director feature that zooms in on the play. Included in NFL 2K2 are all the teams and plays from the 2001-2002 season, including stadiums and uniforms.' FROM games WHERE igdb_id = 8845 ON CONFLICT (game_id, language_code) DO NOTHING;
