INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leiji Matsumoto 999: Story of Galaxy Express 999', 'An adventure game for the PlayStation based on Leiji Matsumoto''s Galaxy Express 999. You assume the role of Tetsurô Hoshino, a young boy that witnesses the murder of his mother by Count Mecha, a cyborg who hunts humans for sport. In his quest for revenge, Tetsurô meets Maetel, a mysterious lady who offers him a pass for the prestigious "Galaxy Express 999", a space train that travels from Earth to the Andromeda galaxy. There Tetsurô could get a mechanized body for free and thus be able to challenge Count Mecha.' FROM games WHERE igdb_id = 70283 ON CONFLICT (game_id, language_code) DO NOTHING;
