INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Roads', 'Venice. The tight winding alleys and long dirty canals. Easy to become lost here, where every street emerges somewhere unexpected. In the central square a scaffold has been erected for your neck, and if only you can escape for long enough you might survive, but in this city all roads lead back to Piazza San Marco and the Hanging Clock.' FROM games WHERE igdb_id = 60144 ON CONFLICT (game_id, language_code) DO NOTHING;
