INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercar Street Challenge', 'Climb in, get behind the wheel and buckle up for the ride of your life! Street Lethal is no ordinary racing game. Rampage through the streets of spectacular interactive city envrionments such as London and Paris. Hold on tight as you drive the hottest modern concept cars. If you''ve ever dreamed about driving high-class speedsters like the Callaway C12, the Pagani Zonda C12-S, and the Fiorvanti F100, you''re in luck. Travel through the streets of the world''s most prominent cities in a race of the ultimate driving machines. You''ll hit speeds above 200 miles per hour as you dodge through street fairs, back alleys, and more in an attempt to win. Experience the power of driving these previously inaccessible vehicles, enjoying 3D graphics and an awesome soundtrack all the while.' FROM games WHERE igdb_id = 43220 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43220 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
