INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fort Boyard', '"Fort Boyard" is a videogame developed by Microids and published by Nintendo in 2001 for the Game Boy Color. It is based on the international game TV show of the same name, which first became popular in France in the early 1990s. Teams of 4 players compete in physical and mental challenges to earn keys that unlock a trove of prizes. Players meet famous Fort Boyard characters and animals in various situations.' FROM games WHERE igdb_id = 50030 ON CONFLICT (game_id, language_code) DO NOTHING;
