INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic & Friends', 'Dr. Robotnik''s new plan is to pour a ton of filth into the Floating Island''s ocean, and is dropping Badnik''s everywhere. Sonic and his friends find themselves on Tails Island, a small island next to the Floating Island, but now they will have to go out in search of the Cosmic emeralds before the filth ends all life on the island.' FROM games WHERE igdb_id = 324960 ON CONFLICT (game_id, language_code) DO NOTHING;
