INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Summit', 'Snowboarders have never felt welcome on Mt. Garrick, a once quiet and peaceful ski resort. Chief O'' Leary, the resident ranger, has led the charge against boarders and limited their access to certain sections of the mountain. But the situation has progressed. Chief O''Leary has mysteriously closed the summit to all boarders and is trying desperately to drive them off the mountain.' FROM games WHERE igdb_id = 3869 ON CONFLICT (game_id, language_code) DO NOTHING;
