INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QBz', 'Here are a few things you need to know about QBz: They like to travel in groups, they cry when left on the board, and they star in one of the most hilarious and addictive puzzle games around! Click on the clusters of cute little squares (the QBz themselves) to clear them from the screen. Clear them all and you get happy QBz and a cool animation. Leave a few on the screen and watch them cry! Fun, silly, and adorable!' FROM games WHERE igdb_id = 78079 ON CONFLICT (game_id, language_code) DO NOTHING;
