INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cluedo-chronicles-fatal-illusion', 50799, '2001-01-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25j7.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cluedo Chronicles - Fatal Illusion', 'Welcome to Fatal Illusion, Episode 1 of the Clue Chronicles Mystery Series; an expansive, richly detailed world where YOU actually solve the mystery! It''s New Year''s Eve 1938. On board the private yacht of the wealthy and eccentric Ian Masque, you find yourself part of a "select" group of guests invited to an "unusual" New Year''s Eve party. Each guest has a story to tell, but their connection to you and to each other remains hidden. Something strange is bound to happen, and everyone is a suspect. Get ready to put your best deductive reasoning to work and unravel the true story behind this game. Along the way you''ll find challenging puzzles to solve and mini-mysteries to unlock. This totally engaging mystery adventure is sure to keep super sleuths entertained from the opening scene to the exciting cliffhanging climax.' FROM games WHERE igdb_id = 50799 ON CONFLICT (game_id, language_code) DO NOTHING;
