INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noodle Fight', 'Gorillaz-guitar-guru Noodle stars in her very own game! During the shoot for the Gorillaz'' Clint Eastwood video, the co-star stunt ghoulies got carried away and decided to drag bassman Murdoc off to their lair... you play as Noodle and must track down Murdoc and return him to the safe confines of Gorillaz'' KONG Studios! Dodge the grasping hands of the ghoulies and those pesky flapping bats, evade the licking flames of the underground inferno and heed the warnings of Del Tha Funky Homosapien! Beware the Boss ghoul and you''ll free Murdoc and return him to safety!' FROM games WHERE igdb_id = 269313 ON CONFLICT (game_id, language_code) DO NOTHING;
