INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fifa-soccer-2002-major-league-soccer', 701, '2001-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vai.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8z3y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Soccer 2002: Major League Soccer', 'FIFA Football 2002 (known as FIFA Soccer 2002: Major League Soccer in North America, and FIFA 2002: Road to FIFA World Cup in Japan), commonly known as FIFA 2002, is a football video game released in 2001, produced by Electronic Arts and released by EA Sports. FIFA 2002 is the ninth game in the FIFA series. Power bars for passes were introduced, and dribbling reduced in order to attain a higher challenge level. The power bar can also be customised to suit the gamer''s preference. The game also includes club emblems for many more European clubs as well as for major Dutch clubs such as PSV, AFC Ajax and Feyenoord, although there was no Dutch league of any kind (they were under the "Rest of World" header). This game also features, for the first time, the Swiss Super League, at the cost of excluding the Greek League. A card reward system licensed from Panini was also introduced where, after winning a particular competition, a star player card is unlocked. There is also a bonus game with the nations that had automatically qualified for the 2002 World Cup (France, Japan and South Korea), in which the player tries to improve the FIFA ranking of their chosen team by participating in international friendlies. Many of the international teams in the game are not licensed (some of them down to the players'' names like the Netherlands), as well as smaller countries such as Barbados, who were only given numbers as player names. Also, to date, this was the last FIFA edition (not counting the World Cup versions) to feature the Japanese national team, since Japan Football Association would go on to concede exclusive rights to Konami''s Pro Evolution Soccer series. FIFA Football 2002 ran for 10 years as the last FIFA to have only one person as cover, before Lionel Messi appeared alone on FIFA 13.' FROM games WHERE igdb_id = 701 ON CONFLICT (game_id, language_code) DO NOTHING;
