INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rolie Polie Olie: The Search for Spot', 'Join Olie in an interactive learning experience for kids 2-5 based in the social and moral universe of the show. In Playhouse Disney''s Rolie Polie Olie: The Search for Spot, help Olie find his dog Spot who is running around the house! Explore the amazing automated Polie household, create your own robotic musical score, transform ordinary furniture into amazing rockets and pirate ships, hone visual skills while capturing run-away colors and plumb the untold depths of Tubby, the Polie bathtub. Children will be able to interact with their favorite Rolie Polie Olie characters, in a magical exploratory adventure where "Learning is Powered by Imagination."' FROM games WHERE igdb_id = 209366 ON CONFLICT (game_id, language_code) DO NOTHING;
