INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bleemcast-for-metal-gear-solid', 315682, '2001-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rwl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctt0r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleemcast! for Metal Gear Solid', 'Bleemcast!, also known as Bleem! for Dreamcast, is an unlicensed commercial emulator developed and published by Bleem! for use with the Sega Dreamcast. By taking advantage of loopholes within the Dreamcast''s Mil-CD format, Bleemcast! software allows the system to run select PlayStation games, often with enhanced graphics. Each Bleemcast! disc is intended for a single PlayStation game only, and is utilized by first booting the Dreamcast with the Bleemcast! disc, and then later swapping in the PlayStation game at a specific time. While running under Bleemcast!, PlayStation games adopt anti-aliasing and bilinear filtering, as well as an increased resolution of 640x480 (double the PlayStation''s 320x240). All released Bleemcast! games require a dedicated VMU to play and save progress, while also supporting the Jump Pack for vibration.' FROM games WHERE igdb_id = 315682 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 315682 AND p.igdb_id = 23 ON CONFLICT DO NOTHING;
