INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stretch Panic', 'Stretch Panic is an action/platform video game designed by Treasure Co. Ltd. It was a landmark title for the developer as it was their first game to feature movement on a 3D plane; prior to Stretch Panic they had exclusively been a developer of 2D titles. The game revolves around a girl named Linda who has the power to pinch, stretch, and bend objects and enemies with a magic scarf as she battles her evil sisters.' FROM games WHERE igdb_id = 28502 ON CONFLICT (game_id, language_code) DO NOTHING;
