INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure at the Chateau d''Or', 'The princess heir has chosen you as her hero and you lead the quest to unlock the secret of the fabulous Chateau d’Or. Call upon your intelligence, intuition and newfound knowledge to survive and bring the princess safely to her goal. Test your powers of observation and intellect in this thrilling game. The fate of the Princess of the Chateau d’Or lies in your hands.' FROM games WHERE igdb_id = 78189 ON CONFLICT (game_id, language_code) DO NOTHING;
