INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpgate: The Reconstruction Initiative', 'Jumpgate: The Reconstruction Initiative is a space combat MMO in which players pilot spacecraft. Players accumulate wealth through mining, trade, and combat. Funds are used to purchase upgrades for their craft. The game divides space into sectors containing asteroids and space stations. Travel between sectors takes place via jumpgates.  PvP Combat  PvE Combat  Mining  Manufacturing  Trading  Persistant Universe encompassing over 150 sectors  3 playable factions  2 non-playable factions  Joystick support' FROM games WHERE igdb_id = 765 ON CONFLICT (game_id, language_code) DO NOTHING;
