INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geep Simulator', 'The Geep Simulator game, better known as Final Drive, was a Gorillaz 3D flash and shockwave-based simulator game available on the Gorillaz.com website, at Kong Studios'' carpark, during Phase 1 and also included on the Celebrity Take Down DVD, where you could drive the Gorillaz'' Geep on a (somewhat limited) open 3D area. The player controls the Gorillaz'' Geep with the arrow and R keys and space bar on their keyboard.' FROM games WHERE igdb_id = 191309 ON CONFLICT (game_id, language_code) DO NOTHING;
