INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angel Present', 'Angel Present takes place in a 2.5D environment with adventure elements in 2 different worlds, with 3d battles. The game mixes these more action-based elements, with static screens and text and CG movies. The story centers around the main protagonist stumbling across a fairy and soon discovering they have magical powers.' FROM games WHERE igdb_id = 267405 ON CONFLICT (game_id, language_code) DO NOTHING;
