INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dinosaur''us', 'Dinosaur''us is a puzzle game with Lemmings-like gameplay. Each level is a scrolling screen where baby dinosaurs hatch. The player has to click on them as they come out from their nests, using their abilities to create a path so they can reach the parent dinosaur that acts as the level exit.' FROM games WHERE igdb_id = 147510 ON CONFLICT (game_id, language_code) DO NOTHING;
