INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kawasaki Fantasy Motocross', 'This Kawasaki-licensed motocross racing game gives players the possibility to ride one of three Kawasaki two-stroke dirtbikes (KX125, KX250, or KX500) over 7 tracks in diverse scenarios. These range from a farm in the countryside, over Egyptian ruins, to an active volcanic area.' FROM games WHERE igdb_id = 91690 ON CONFLICT (game_id, language_code) DO NOTHING;
