INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Granbo', 'Granbo is a RPG game released for the Game Boy Advance in 2001. It was only released in Japan. The game''s story focus on a young boy named Kakeru trying to save the world through the use of robotic animals. Granbo was also released for Nintendo''s Virtual Console for Wii U in Japan.' FROM games WHERE igdb_id = 210778 ON CONFLICT (game_id, language_code) DO NOTHING;
