INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shrek-fairy-tale-freakdown', 18576, '2001-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co987j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr8y1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrek: Fairy Tale Freakdown', 'The wackiest computer-animated film of all time has its own classic hand-held game! Boasting fast-paced thrills and the most hilarious characters ever portrayed in a video game, SHREK: Fairy Tales Freakdown turns the story of the movie into a fighting game that players of all ages will love. Taking six familiar faces from the popular film, Fairy Tales Freakdown pits the unlikely combatants in a series of battles against one another each fight taking place in a classic SHREK environment. Solid gameplay will earn you the right to play as one of three locked characters, and each brawler is characterized by a unique (and highly comical) fighting style. The mostly non-violent fighting closely mirrors the humor of the film, resulting in some truly memorable melees. Using animations that are straight from the film, the game delivers the look and feel that made SHREK so successful. Play alone or take on a friend in this lighthearted, tournament-style fighting game.' FROM games WHERE igdb_id = 18576 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 18576 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
