INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keeper Practise', 'A flash game from a collection from Warner Bros. circa 2001. The collection included games such as Sorting Hat, Wand Shop, Keeper Practise, Seeker Practise, Beater Practise and Chaser Practise. In this game, the player controls the keeper with the mouse defending the 3 goal posts as an oponnent chaser approaches and shoots towards one of the three goal posts and must react when the ball is near the keeper. A hanging jewel flashes red when the ball is reacheable. The player is allowed three "lives" and must aim for a highscore.' FROM games WHERE igdb_id = 291623 ON CONFLICT (game_id, language_code) DO NOTHING;
