INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rugrats-totally-angelica', 2789, '2001-04-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2r7b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9d8u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugrats: Totally Angelica', 'It might be hard to root for the deplorable Angelica Pickles in the RUGRATS television series and films, but she''s the star of this exciting video game. It seems that the oft-disgruntled heroine has decided to put together a little fashion show. It''ll be up to you to help Angelica organize the entire event by seeking out wigs, purses, shoes, clothing, and other accessories from around the neighborhood. The show''s success is entirely in your hands throughout this lighthearted search. All of the usual suspects are here as well, so prepare to get into tiffs with the likes of Chuckie, Tommy, Phil, and Lil. A plethora of mini-games keep things fun, challenging you to perform all sorts of activities based on the hit TV show. Winning these games will earn you rewards that can be used to help get the necessary materials for the fashion show. If the show succeeds, you''ll get to move on to hidden areas for all-new challenges!' FROM games WHERE igdb_id = 2789 ON CONFLICT (game_id, language_code) DO NOTHING;
