INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alchemy', 'From the creators of Diamond Mine (Bejeweled) comes another addictive masterpiece! Alchemy combines elements of both puzzle and strategy games that will keep you thinking (and playing) for hours. Place runes on the board to form paths all the way across. Complete a path and it turns to gold; turn the board gold and move to the next level. Can''t use a rune? Toss it into the cauldron, but do this too many times and it''s Game Over! A great version of the web game classic!' FROM games WHERE igdb_id = 3754 ON CONFLICT (game_id, language_code) DO NOTHING;
