INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Rage', 'The Rage is one of the very few examples of 3D scrolling beat’em up for PC; it guarantees a great playability, never forgotten by old style arcade players, together with the new stunning graphics, thanks to modern PC hardware, and really strong musics. It allows to fight with up to four players, using the same PC or Internet and LAN connections, in real brawls against a great number of enemies with a wide range of easy-to-do moves.' FROM games WHERE igdb_id = 76756 ON CONFLICT (game_id, language_code) DO NOTHING;
