INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop''n Music Animelo 2', 'Pop''n Music Animelo 2 (Pop''n Music アニメロ2) is a rhythm video game developed by Konami and released on Arcade platforms in 2001 in Japan. It is a spinoff entry in the Pop''n Music series. Unlike the previous Animelo entry, the game didn''t have a console release.' FROM games WHERE igdb_id = 72881 ON CONFLICT (game_id, language_code) DO NOTHING;
