INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RuneScape Classic', 'RuneScape Classic (also known as RSC, RS1 or RS Classic) was the first official release of RuneScape (DeviousMUD being the precursor). RuneScape Classic was publicly released on 4 January 2001. It was later replaced on 29 March 2004, with what was then known as RuneScape 2. On 23 May 2018, Jagex announced that RuneScape Classic would be permanently closing on 6 August 2018 due to numerous unfixable problems with the game.' FROM games WHERE igdb_id = 138173 ON CONFLICT (game_id, language_code) DO NOTHING;
