INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Valle Magica', 'An ad games from the Kinder Fresh Adventures series, developed to advertise italian snacks like Kinder Pinguì e Kinder Fetta al Latte. The other games in the series are La Giungla Tenebrosa, La Fabbrica Spaziale and La Montagna Misteriosa. They were all released as separate CDs, but are in fact reskins with very minor changes to the gameplay of the same levels, making it very difficult to classify them either as single games or expansions.' FROM games WHERE igdb_id = 145975 ON CONFLICT (game_id, language_code) DO NOTHING;
