INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gallop Racer 2001', 'Gallop Racer 2001 is a horse racing video game focused on simulating the jockey racing experience through a season mode. The game bases its challenges on knowing how your horse handles each race rather than pure driving. It contains breeding mechanics, a myriad of race types to try and jockey point management.' FROM games WHERE igdb_id = 20144 ON CONFLICT (game_id, language_code) DO NOTHING;
