INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casper: Spirit Dimensions', 'Spiral into phantom dimensions where you will fiercely battle for the fate of the spirit world! Portals will transport you to mysterious realms that are populated by ghosts of the past, present and future; all possessed by the evil Kibosh. Use your powers of flight and fright to become the quickest, smartest and most powerful ghost in the Spirit Dimension!' FROM games WHERE igdb_id = 3850 ON CONFLICT (game_id, language_code) DO NOTHING;
