INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Riders', 'Wild Riders is a cel-shaded bike racing game released for Sega NAOMI 2 arcade hardware in 2001. You pick from one of two characters Keith Raven or Trish Moon as they make their great escape from the police, racing through the streets of comic city as they simultaneously weave through traffic and avoid the cops.' FROM games WHERE igdb_id = 58381 ON CONFLICT (game_id, language_code) DO NOTHING;
