INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 79: The Shisenshou', 'The Shisenshou is a puzzle game similar to the Shanghai series since the player have to find 2 pieces of the same shape & colour that are alone to join them and make them dissappear, the player have to follow an order since he can make 2 pieces dissappear if they are surrounded by other different pieces, except when the 2 equal pieces are one next to the other. To advance to the next stage the player has to clear of the pieces in each stage before the time ends.' FROM games WHERE igdb_id = 203073 ON CONFLICT (game_id, language_code) DO NOTHING;
