INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elite Forces: WWII - Iwo Jima', 'Join the ranks of the U.S. marines as you embark on a treacherous and chaotic amphibious beach landing, defeat a vast network of interconnected pillboxes and emplaced guns, negotiate your way through perilous mine fields and enemy bunkers to track down and eliminate an elusive enemy. Experience the story of one rifleman’s heroic struggle to survive and prevail among the nearly 100,000 combatants who warred for 36 days for possession of the island of Iwo Jima.' FROM games WHERE igdb_id = 25285 ON CONFLICT (game_id, language_code) DO NOTHING;
