INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Karate Joe', 'There''s a new boss in town, and his gangs are taking over the city. He''s got thugs on every corner waiting to take you out. But you''re not a run-of-the-mill videogame character. You''re Karate Joe, and you''re going to fight your way through 18 levels to free the city in this side-scrolling action-adventure.' FROM games WHERE igdb_id = 50062 ON CONFLICT (game_id, language_code) DO NOTHING;
