INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('frenzy-express', 233281, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8op5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctn9t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frenzy Express', 'Frenzy Express is a fast-paced simulation game that builds on the worldwide fad "Scooters." The machine''s biggest feature is the level of interaction the player gets. The machine contains a actual scooter which the player uses to travel around the stages. The handlebar enables the player to steer and the brake is locate at the back of the scooter. Acceleration is achieved by a wheel with grips, which is located on both sides of the scooter. The player push off the wheel much like he/she would push off the ground if you were riding a real scooter. Gameplay is similar to Crazy Taxi, except instead of picking up and dropping off passengers, the player is a courier and must pick up and drop off packages. The way you reach the drop off point is entirely up to the player, but there is a time limit and each second that ticks by means less money at the drop off point. To make the game more fun, there are many ramps and other objects suitable for jumping and performing aerial acrobatics which earns the player bonus points.' FROM games WHERE igdb_id = 233281 ON CONFLICT (game_id, language_code) DO NOTHING;
