INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Resort Tycoon II', 'Ski Resort Tycoon II the sequel to Ski Resort Tycoon. The game combines the best features of the original with new elements and improvements. Add ski runs and buildings to your resort, while managing your income and trying to keep the visitors happy. Better graphics, bigger maps and a wide variety of animations distinguish this product from its predecessor. The game has the same general atmosphere as the original, but with improved graphics and user interface. More equipment, additional views including 360 degrees, better and more complete buildings and a new and improved sound.' FROM games WHERE igdb_id = 73177 ON CONFLICT (game_id, language_code) DO NOTHING;
