INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('i-modo-mo-issho', 244003, '2001-05-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6clt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclxmk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Modo Mo Issho', 'i Modo Mo Issho (iモードもいっしょ) is a video game developed by Bomber Express and published by Sony Computer Entertainment Inc. It was released on May 24, 2001 for the PlayStation, and it is the third game and an expansion pack for Doko Demo Issyo and Koneko Mo Issho in the Doko Demo Issyo Series. Like Koneko Mo Issho, save data for Doko Demo Issyo is required to play it. It features additional content, such as new environments and music. It''s most notable feature is its connection with the i-Mode phone service, a Japanese mobile phone service provided by DoCoMo that allowed an early form of Internet connectivity with mobile phones. Players can use an adapter to connect the phone to the Playstation console and connect to the online service, which allows players to to communicate to other players and the Pokepi, similar to the PocketStation. It is also the last Doko Demo Issyo game to be released exclusively on the PlayStation. The online service ended on December 15th, 2002, but the offline features of the game were still available.' FROM games WHERE igdb_id = 244003 ON CONFLICT (game_id, language_code) DO NOTHING;
