INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moderngroove-ministry-of-sound-edition', 43632, '2001-08-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/v0ge61ndgvipf3mjvkpc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moderngroove: Ministry of Sound Edition', 'Moderngroove: Ministry of Sound Edition is 5 hours of brand-new electronica music from Europe''s leading DJs along with thousands of dynamically-generated 2D and 3D visuals that synch to the music. It''s a one-of-a-kind product that provides hours of entertainment for the entire house party.  What MTV Music Generator is to music mixing, Moderngroove is to visual mixing. The product allows users to create their own visuals with the Visual Mixer - even input your own text via USB keyboard or controller. Or simply turn on the "Karaoke mode" to incorporate the lyrics of each song into the synching visuals.  Moderngroove is the world''s largest independent dance music label and is world-renowned for their compilation CDs, lifestyle magazine, travel tours, and of course, the South London nightclub that started it all.' FROM games WHERE igdb_id = 43632 ON CONFLICT (game_id, language_code) DO NOTHING;
