INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sutakomi: Star Communicator', 'Sutakomi: Star Communicator is a game by Konami based on traditional pet-raising style games, such as Tamagotchi. The player takes care of a cute "Star Communicator", raising them into adulthood before sending them out into the world to work a job.This title also supported the Mobile GB Adapter which allowed players to send and receive mail online, buy items for the pet, and paid content was also used in a "Star Marriage" feature where two players could marry their pets to each other.' FROM games WHERE igdb_id = 49804 ON CONFLICT (game_id, language_code) DO NOTHING;
