INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes Chronicles: The Sword of Frost', 'Heroes Chronicles: The Sword of Frost is the eight and final game in the Heroes Chronicles series. Tarnum must beome a Dungeon Overlord of Nighon to stop his former friend, the Elven Hero Gelu, from discovering the Sword of Frost. This campaign was one of two included in the single-disc installment, The Final Chapters.' FROM games WHERE igdb_id = 8140 ON CONFLICT (game_id, language_code) DO NOTHING;
