INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sergueis Destiny', 'The evil sorcerer Blackmagic took over a village named Jolimy. Only a lone apprentice magician named Serguei can eventually defeat him and liberate his homeland. Serguei''s Destiny is made with the AGI interpreter, which was the engine used for Sierra''s adventure games in mid- to late 1980''s (such as for example the first two Space Quest games). The game is primarily an adventure, but there are RPG elements as well: Serguei accumulates experience and learns new spells by completing quests.' FROM games WHERE igdb_id = 230188 ON CONFLICT (game_id, language_code) DO NOTHING;
