INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kioh Gyoku', 'Kioh Gyoku (稀翁玉, lit. "Rare Venerable Orb") is a vertical-scrolling danmaku shoot ''em up, and is the second official game in the Seihou Project by "Shunsatsu sare do?" (at time part of Amusement Makers). It was released specifically for the Windows operating system. It is a unique game where two players indirectly battle one another by charging and releasing charge attacks and bombs upon the other player, similar in the style of Phantasmagoria of Dim.Dream.' FROM games WHERE igdb_id = 123607 ON CONFLICT (game_id, language_code) DO NOTHING;
