INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Basketball 2001', 'Do you have what it takes to pound the boards and charge the net? here''s your chance to find out build a championship basketball team of your dreams. Direct all the action, set the positions and call the plays. Earn offensive and defensive power-ups, play head-to-head it''s easy to learn and fun to play! it''s the chance of a lifetime to play with the pros in your own backyard.' FROM games WHERE igdb_id = 50297 ON CONFLICT (game_id, language_code) DO NOTHING;
