INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pingu and Friends', 'Pingu and Friends is a collection of ten activities for players of any age based on the BBC clay-mated animated children''s Pingu TV series. Players use an interactive mitten cursor to interact with many of the game''s activities, including dragging objects, counting several items and drawing in the Art Studio activity. Some of the games (particularly ''Save Pinga'') only utilise the keyboard arrow keys. The activities are split into two locations: inside Pingu''s house and outside the house.' FROM games WHERE igdb_id = 130803 ON CONFLICT (game_id, language_code) DO NOTHING;
