INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bob the Builder: Can We Fix It?', 'Get ready for fun, excitement and non-stop laughs with Bob the Builder and his Team on the PlayStation game console. Join Bob in 8 Fix it Fun activities that include Bubble Trouble, Where''s Prichard, Hedgehog Rescue, and Wendy''s Birthday. With varied difficulty levels, Bob the Builder voices, music, and characters from the TV show, kids of all ages will be saying, Can we fix it, yes we can!' FROM games WHERE igdb_id = 44890 ON CONFLICT (game_id, language_code) DO NOTHING;
