INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Internet: legko i prosto!', 'The Internet is really easy and fun! It''s full of fun adventures, and you''ll learn how to navigate the global network with familiar characters like Globi and his companions. You''ll explore the magical world of the Internet, learn how to use browsers and email, and understand the basics of online security.' FROM games WHERE igdb_id = 316480 ON CONFLICT (game_id, language_code) DO NOTHING;
