INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-realms', 606, '2001-11-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ei7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqsa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Realms', 'Kenji, exiled heir to the Dragon throne, must stake his claim in a chaotic world wracked by the subversive intrigues of the Serpent, Wolf, and Lotus clans. Shall he vanquish the land under a campaign of malevolence and terror or restore the war-torn realm to its former glory? Enter Battle Realms and choose your destiny. Explore the history that led up to the events in Battle Realms in Battle Realms: Winter of the White Wolf. Scattered and unorganized, your enslaved Wolf brethren hunger for revolt against their corrupt Lotus Clan masters. You must unite them. You must lead them. You must free them. Battle Realms is fantasy real-time strategy game inspired by the stories told in kung-fu movies and oriental mythology. Develop your tiny peasant village into a highly trained and deadly efficient clan of warriors who are ready to die with your name on their lips. Experiment with Unit Alchemy and turn villagers into one-of-a-kind fighters like Samurai Cannoneers, Bandits, Geisha, and scores of other mythical warriors. Defend your people against the hordes of barbarians, evil magicians, and deadly ninjas.' FROM games WHERE igdb_id = 606 ON CONFLICT (game_id, language_code) DO NOTHING;
