INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Luke: Wanted!', 'Based on the famous comics series about good cowboy Lucky Luke. Now the Daltons are let out from jail and robbed the bank, and you have to chase them shooting at the bad guys, collecting extra lives, ammunition and dynamites, and collecting the four aces to access the bonus level. Meeting with the dog Rintincan is a checkpoint. Characters of the game points you where to go next.' FROM games WHERE igdb_id = 49331 ON CONFLICT (game_id, language_code) DO NOTHING;
