INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sagashi ni Ikouyo', 'You are a young adventurer, looking for challenge. Travel through deep dungeons and battle those who would seek to stop you. A large cast of characters aid and propel players in this treasure hunting, monster battling adventure game. Magic, weaponry and team cooperation will see them through their quests.' FROM games WHERE igdb_id = 85778 ON CONFLICT (game_id, language_code) DO NOTHING;
