INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run=Dim as Black Soul', 'A Turn-Based Strategy RPG based on the anime series Run=Dim, set in a dystopian future where 1/10th of Japan has sunk due to global warming and an evil military organization named "JESAS" has set it''s sight on controlling the future of Japan with mechas. Being the second game in the series (the first being "The Mech Smith Run=Dim" for the PlayStation 2) developed by Idea Factory.' FROM games WHERE igdb_id = 119205 ON CONFLICT (game_id, language_code) DO NOTHING;
