INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cabelas-big-game-hunter-ultimate-challenge', 45298, '2001-12-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dctimti24wzzkilpvwti.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Big Game Hunter: Ultimate Challenge', 'The Cabela line has made major waves on the PC for years, and now it''s ready to bring its unique brand of hunting to the PlayStation. Realistic hunting simulation is the aim, and CABELA''S BIG GAME HUNTER: Ultimate Challenge delivers on many levels. Two different career-oriented modes allow you to hunt for elk, deer, and other tricky prey over the course of numerous detailed levels. You''ll have all of the maps, vehicles, and weaponry you could ever need in order to get the job done, and you''ll need all of the help you can get The wilderness never seems to end in this expansive title. If you need some justification to kill animals, you can join forces with the Department of Natural Resources and help to keep the wolf and bear populations in check (just as brutal a process as deer hunting, mind you). There are adjustable skill settings to ensure that gamers of all walks get their money''s worth, and you can even select an x-ray option that aids you in lining up your shots by showing you your prey''s internal organs.' FROM games WHERE igdb_id = 45298 ON CONFLICT (game_id, language_code) DO NOTHING;
