INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prince Naseem Boxing', 'Fight one-off bouts, compete in tournaments or become a career boxer and slug it out for the World Title Belt. Lightning play speed allows you to dodge, block, weave and hit back at a blistering pace. With 16 world champion boxers to compete against and four modes of play this game offers the most complete boxing experience on Game Boy Color.' FROM games WHERE igdb_id = 50024 ON CONFLICT (game_id, language_code) DO NOTHING;
