INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Everblue', 'Everblue is an adventure game based on scuba diving. The player takes the role of a scuba diver salvaging items from sunken ships and photographing underwater wildlife while either avoiding or confronting predators like sharks. The game also features an inventory system for collected objects, healing items, weapons, and tools, as well as an above water town with shops and NPCs.' FROM games WHERE igdb_id = 37082 ON CONFLICT (game_id, language_code) DO NOTHING;
