INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallacy of Dawn', 'In a world that never quite got over the ''80s, Delarion Yar dispenses quarters for the local arcade... badly. A software pirate from better days, he''s crossed the wrong people one too many times. Locked into the city of New Haz with a criminal record, he''s reached his lowest point and he''ll do anything to get out. A splatterpunk mystery in an alternate future.' FROM games WHERE igdb_id = 57613 ON CONFLICT (game_id, language_code) DO NOTHING;
