INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Les Visiteurs: La Relique De Sainte Rolande', 'Les Visiteurs: La Relique De Sainte Rolande is the sequel to Les Visiteurs: Le Jeu and is based on the film The Visitors II: The Corridors of Time. This time, the sequel is much more action-oriented, and the view is 3rd-person. You must find the parts of the medallion, but also fight, use weapons and even play bowling games.' FROM games WHERE igdb_id = 126077 ON CONFLICT (game_id, language_code) DO NOTHING;
