INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Taisen 3: Paris ha Moeteiru ka?', 'Sakura Wars 3 takes place following the events of Sakura Wars 2. Series protagonist Ichiro Ogami joins the newly formed Paris Assault Troupe to train their own Flower Division, an all-female unit dedicated to fighting supernatural threats against the city while maintaining their cover as a cabaret act. The Paris Assault Troupe must learn to work together to defend their city against a series of mysterious phantoms seeking vengeance against Paris for their fallen ancient civilization.' FROM games WHERE igdb_id = 80143 ON CONFLICT (game_id, language_code) DO NOTHING;
