INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Men: Omega Soldier', 'Created in a covert laboratory by splicing DNA from the strongest and most skilled soldiers, the "Omega Soldier" has been given the strength and weapon skills to become the Tan army''s worst high-tech threat! Army Men: Green Rogue incorporates a 3rd person shooter with coin-op shoot ''em style gameplay that will raise the heartbeat of anyone who dares to accept the challenge.' FROM games WHERE igdb_id = 43766 ON CONFLICT (game_id, language_code) DO NOTHING;
