INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splashdown', 'Splashdown is a water racing video game for the Xbox and Sony PlayStation 2. It can be played by one or two players. Splashdown is quite similar to Nintendo''s Wave Race series. Players take control of a personal water craft as they race against each other on various courses. Players must pass the correct side of buoys on the way or the personal water craft may stall as a penalty or they get splashed by a whales tail.' FROM games WHERE igdb_id = 6149 ON CONFLICT (game_id, language_code) DO NOTHING;
