INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zenfar: The Adventure', 'Zenfar: The Adventure is a science fiction RPG. Gameplay shows an isometric view of your character from above; you move him by clicking on onscreen places or items with your mouse, similar to Diablo or Fallout. Gameplay is in real time. After creating a character, you must explore the alien world of Zenfar, figure out how to defeat a series of force fields dividing Zenfar into separate habitats, and unite the inhabitants against your alien overlords.' FROM games WHERE igdb_id = 73599 ON CONFLICT (game_id, language_code) DO NOTHING;
