INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom vs. SNK: Millennium Fight 2001', 'Capcom vs SNK: Millennium Fight 2001 is an unlicensed port of Capcom vs. SNK: Millennium Fight 2000. Presumably based on the work done on the Game Boy Color port of Street Heroes, there are possibilities that Ei-How Yang was the main programmer of this game as well, despite unproven and incorrect assumptions of Makon Soft being involved.' FROM games WHERE igdb_id = 247455 ON CONFLICT (game_id, language_code) DO NOTHING;
