INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jetracer', 'Jetracer is a Racing game, developed by Theyer GFX and published by Midas Interactive Entertainment, which was released in Europe in 2001. Race over some of the biggest waves on earth and experience the controls of four types of jet watercraft from a 700cc stand-up model, to an awesomely powerful 1200cc sit-down machine (Multiplayer Options/ Four different beach locations/ Freeride and Extreme Trick mode/ Championship mode)' FROM games WHERE igdb_id = 43760 ON CONFLICT (game_id, language_code) DO NOTHING;
