INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outlive', 'Outlive is a Brazilian real-time strategy computer game developed and produced by Continuum Entertainment. It is a mission-based real-time strategy game where the player controls either the human military or robot forces and attempts to eliminate all opposing forces. It was initially released in 2000 in Brazil (2001 for the rest of the world), and was the second and most successful product of Continuum. The game was one of the few Brazilian games to be published by a mainstream AAA publisher. It was published in the United States and Europe by Take-Two Interactive.' FROM games WHERE igdb_id = 11792 ON CONFLICT (game_id, language_code) DO NOTHING;
