INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('reggies-adventures-part-1-escape-from-paradise', 230502, '2001-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z3x.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reggie''s Adventures: Part 1 - Escape From Paradise', 'You play the part of ''Reggie Rich'', an aristocratic playboy who crashes his helicopter and gets marooned on a tropical island. Local fisherman ''Randy Muffin'' offers to take Reggie back to his yacht but only after completing a challenge, which luckily enough for Reggie is to seduce all the gorgeous Island girls! However, it''s not an easy task to charm the girls, so Reggie''s travels will include gambling, playing the slot machines, solving cryptic puzzles, and lots, lots more......All set within spectacular locations including hot tubs, lap dancing club, casino, and you can even go to the movies! Can you help Reggie seduce all the sexy girls? If so, the rewards will be a treat for both Reggie and you!' FROM games WHERE igdb_id = 230502 ON CONFLICT (game_id, language_code) DO NOTHING;
