INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jackie Chan Adventures: Legend of the Dark Hand', 'Are you Chan enough? As Jackie Chan, martial arts master and expert archeologist, you have | to take a quest around the world to defeat the evil Dark Hand organization. Their sinister demons seek to enter the earthly realm and it''s up to you and your cunning wit, martial arts skill and magical scrolls to stop them in their tracks.' FROM games WHERE igdb_id = 8155 ON CONFLICT (game_id, language_code) DO NOTHING;
