INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-shootout-2002', 20265, '2001-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/trkfzv8lmawwjm0t5bwk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA ShootOut 2002', 'If you love basketball (and you know you do), get ready for best thing since sliced bread. NBA SHOOTOUT 2002 takes the popular SHOOTOUT franchise to new heights, featuring the most realistic-looking action to date. The player models are created from a combination of photographs, motion-capture animation, and texture mapping which means the superstars and benchwarmers alike will appear just as they do in real-life. An updated game engine gives the play the feel of the NBA, and all of the new rules changes are in effect, too. The courts look like their real-life counterparts, with updates included for new floors like Seattle''s. You choose your team, execute any desired trades, set your starting lineup, and pick through the playbook to create the most dominant squad in the league. High-flying dunks, touch shooting, and a sophisticated foul system make the NBA SHOOTOUT 2002 even more incredible than the beloved series installments that paved the way.' FROM games WHERE igdb_id = 20265 ON CONFLICT (game_id, language_code) DO NOTHING;
