INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxing Fever', 'BOXING FEVER is the ultimate fighting challenge for the Nintendo Game Boy Advance system. Take on over eight of the fastest, strongest, and most brutal boxers from all over the world, or challenge your friends in a head to head knock down battle to prove who''s the biggest, baddest boxer of all time.' FROM games WHERE igdb_id = 6335 ON CONFLICT (game_id, language_code) DO NOTHING;
