INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Floigan Bros.', 'Large and lovable Moigle has a Secret Project that will keep the greedy Baron Malodorous and his gang of Mercenary Cats from taking over the Floigan Junkyard. Unfortunately, Moigle has lost the parts he needs to complete his project so he must enlist the help of his quick-witted older brother, Hoigle. Together, the Floigan Brothers play games and solve puzzles, all while defending their family turf!' FROM games WHERE igdb_id = 22050 ON CONFLICT (game_id, language_code) DO NOTHING;
