INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey to Stonehenge', 'In this 3D Donkey Kong clone, players take the role of a caveman looking for Stonehenge. Players travel along paths to get to the green part of the board, where a giant monkey is tossing barrels at them. Through 30 levels, players must also avoid cactus, birds, rhinos, and falling rocks while collecting bones to get to the next level.' FROM games WHERE igdb_id = 69812 ON CONFLICT (game_id, language_code) DO NOTHING;
