INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Italian Job', 'The Italian Job is a video game based on the 1969 film of the same name. The game features a story mode based on the movie, and a multiplayer "party" mode where players compete through several different circuits in London and Turin, as well as a single player practice mode where the player can develop skills needed for completing the story mode.' FROM games WHERE igdb_id = 135936 ON CONFLICT (game_id, language_code) DO NOTHING;
