INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wild Thornberrys: Chimp Chase', 'Wild Thornberrys: Chimp Chase TV?s favorite explorers are coming to the Game Boy Advance this fall. Darwin has been kidnapped and Eliza and her family must travel the globe in search of her chimp. In this side-scrolling adventure game, players travel through 12 exotic levels featuring Africa, South America, Australia and even the Arctic Circle.' FROM games WHERE igdb_id = 49373 ON CONFLICT (game_id, language_code) DO NOTHING;
