INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Family', 'Mario Family is a piece of software for the Game Boy Color released only in Japan to be compatible with Jaguar''s JN-100 sewing machine. The JN-100 came with a cable that would link it to a Game Boy Color, and in the game the player can choose one of several designs that the machine can copy onto fabric. This game is the second Mario sewing game after I Am a Teacher: Super Mario Sweater. It is also the last Mario game on the GBC.' FROM games WHERE igdb_id = 131985 ON CONFLICT (game_id, language_code) DO NOTHING;
