INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survival: The Ultimate Challenge', 'The concept of the game is to save a random group of people stuck on an island, a desert or another remote location.  By using what the nature has to offer, the player can, for example, use a leaf to make clothes or wood beams to make a shack.' FROM games WHERE igdb_id = 51243 ON CONFLICT (game_id, language_code) DO NOTHING;
