INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-jam-2001', 49903, '2001-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2v7u.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Jam 2001', 'Get even more arcade-style basketball action with NBA JAM 2001. Choose from all 29 NBA teams -- over 140 professional players in all. Get used to the controls and action with the Practice mode, and when you are ready for some real action, try to become NBA champion by playing through the Season. If the Season is giving you a headache, you can skip it and go straight to the Playoffs. No matter what mode you play in, there will be plenty of fastbreaks and rim-rattling jams. Throw even more action into the game with the Fun mode that includes Hot Spots, Hang Time, Half Court Dunks, and On Fire. You can also unlock secret teams like the East and West All-Star teams. Get all of the basketball action you want in the palm of your hand with NBA JAM 2001.' FROM games WHERE igdb_id = 49903 ON CONFLICT (game_id, language_code) DO NOTHING;
