INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candy Stripe: Minarai Tenshi', 'Candy Stripe: Minarai Tenshi is an dating sim adventure game for the Sega Dreamcast. The game takes place in the fictional Holy Angels Hospital. The player is a medical intern, and the game''s objective is to establish personal relationships with one of three incoming nurses over a one-year period.' FROM games WHERE igdb_id = 283327 ON CONFLICT (game_id, language_code) DO NOTHING;
