INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('charge-n-blast', 45822, '2001-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40ev.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dhq5snkgzyt8uingbnko.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charge ''n Blast', 'Charge ''N Blast is a shooting game where you play as one of three marines who have to rid the earth of alien scum. The gameplay is similar to Cabal, you move left and right dodging enemies while charging up you weapons to blast them away. There are three different marines you can choose from, each with their own set of weapons. As usual there is the balanced character (Johnny Rock), a weaker but faster one (Pamela Hewitt) and a slower but stronger one (Nicholas Woods). You can choose to play in one player mode, time attack or two player mode. The missions are broken up into small areas where you have to kill all enemies before moving on to the next area. Each mission ends with a boss character such as a giant insect or a Godzilla-like monster. Use the X, Y or B buttons to choose a weapon, press A to charge and shoot and aim with analog stick. There are different types of weapons that can be used on the different types of enemies. For example the single missiles for far away targets and torpedoes for underwater enemies. You can fire your weapon continuously, but this doesn''t do as much damage compared to a fully charged shot. Charging each shot means you have to aim a little more carefully, but you''ll especially need this in the later levels. You can dodge enemies with the L and R buttons.' FROM games WHERE igdb_id = 45822 ON CONFLICT (game_id, language_code) DO NOTHING;
