INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Karate Advanced', 'How advanced is your karate? Find out in this martial arts game for the Game Boy Advance. Bigger, badder and better than ever before, International Karate Advanced pits you against a series of increasingly skilled opponents, progress from white to black belt in the exciting Tournament and Dojo Game Modes, bump up your score in the demanding Bonus Games and sharpen your skills in the Practice Area.' FROM games WHERE igdb_id = 49292 ON CONFLICT (game_id, language_code) DO NOTHING;
