INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titeuf', 'Titeuf is a party game for Gameboy. Nadia''s picture was torn to thousand pieces. So you go on a treasure hunt with your friends. For each successful challenge, you win a piece of the picture. Playable alone or in multiplayer, 21 minigames are waiting for you.' FROM games WHERE igdb_id = 169133 ON CONFLICT (game_id, language_code) DO NOTHING;
