INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('1193-anno-domini-merchants-and-crusaders', 71494, '2001-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4l79.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scg9qk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1193 Anno Domini: Merchants and Crusaders', '1193 Anno Domini is a trading simulation set in the second half of the Middle Age. You are a little unknown trader. And so are your three rivals, which are either played by the computer or by real players. Now it''s your task to become a rich and powerful merchant and over powering your three rivals. For this task, you have the ability to expand your business through 98 towns, while trading 36 different goods. But you are not just trading the goods, but you also producing them, for this task you have up to 22 production facilities to produce goods for 6 different economy sectors. For maintaining your trade business, you have to protect your goods from thieves or other players, but you must also counteract some external influences, like the weather or plagues. When you gain influence as a trader and are respected by the authorities, they not just help you to protect your goods, but you also gain the ability to do some political decisions (taxation and others). You then also get assigned some tasks to do for the town and the church.' FROM games WHERE igdb_id = 71494 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 71494 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
