INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bille & Trille: Wacky Woods', 'The kindergarten is going on a picnic in the woods, and of course Sammy and Sally together with all their friends are going along with the nutty Fantasy Animal. You will recognise most of the things in the woods until the Fantasy Animal is let out, then strange and magical things start to happen. The Fantasy Animal always accompanies Sammy and Sally. It gives you the choice between activities that you would ordinarily do in the woods and of playing fantasy games that involves using your imagination. By clicking on the fantasy animal you transform the forest into a playground for the imagination.' FROM games WHERE igdb_id = 84364 ON CONFLICT (game_id, language_code) DO NOTHING;
