INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smuggler''s Run: Warzones', 'Race around five unique massive levels transporting various contrabands all the while avoiding police and other smugglers. You are a smuggler working for Frank Luger who''s company will transport anything anywhere. (Except drugs, kids, say no to drugs.) There are over 175 different missions with dozens of different objectives from a simple race to destroying a target to transporting 15 different contraband in less than 20 minutes.' FROM games WHERE igdb_id = 4153 ON CONFLICT (game_id, language_code) DO NOTHING;
