INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dokodemo Hamster 4: Doki-doki Sugoroku Daibouken!', 'Dokodemo Hamster 4: Doki-doki Sugoroku Daibouken! is the fourth game in the Dokodemo Hamster series. In the game the player controls one of 4 different hamsters in a 2d board game that takes place in different parts of an island. The gameplay is the usual in a board game since the player roll a dice to reach different squares of the board, there are mini games and other events around each board table, and the player that win is the one that reachs the end of each board first.' FROM games WHERE igdb_id = 125566 ON CONFLICT (game_id, language_code) DO NOTHING;
