INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple Characters 2000 Series Vol. 05: Highschool Kimengumi - The Table Hockey', 'This Playstation game is a Table Hockey game that features characters from the manga Highschool Kimengumi. The player can choose (at first time) from one of the 5 main characters and have to defeat different characters in the story mode to unlock the gallery mode. The gameplay the player that reach 7 goals first win the match or have more goals than the other at the end of the time. There are also special attacks and special items to active them.' FROM games WHERE igdb_id = 203133 ON CONFLICT (game_id, language_code) DO NOTHING;
