INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman Tournament', 'An S.O.S. from the cosmos signals that planet Phantarion is in trouble! Grab your arsenal and get ready for non-stop action as you blast your way through interactive battlefields and take on up to 4 real-time players. Battle opponents through 8 interactive battlefield mazes! Take on up to 4 players in multi-player blastfests! Fast, furious, explosive bombing adventure!' FROM games WHERE igdb_id = 6334 ON CONFLICT (game_id, language_code) DO NOTHING;
