INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Pro Wrestling', 'Step into the Fire Pro Wrestling ring and experience blistering hot wrestling action that will blow you away! Extreme Wrestlers. Masked Luchadores. Martial Artists. Ultimate Fighters. They''re all here and they all have one mission--win at any cost. Chose Slams. Flying Backbreakers. Pile Drivers. Skull Crushers. No move is too extreme and nothing is illegal unless you get caught!' FROM games WHERE igdb_id = 6407 ON CONFLICT (game_id, language_code) DO NOTHING;
