INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s Pro Skater 2x', 'Tony Hawk''s Pro Skater 2x was designed to take full advantage of the technical capabilities of Xbox. The game features the franchise''s signature gameplay, intuitive controls, all of the levels from both Tony Hawk''s Pro Skater 2 and the original Tony Hawk''s Pro Skater, in addition to more populated environments, brand new levels, realistic special effects and smoother lifelike animations. The inclusion of system link gameplay brings the skateboarding experience to life.' FROM games WHERE igdb_id = 47325 ON CONFLICT (game_id, language_code) DO NOTHING;
