INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mizuki Shigeru no Shin Youkai-den', 'One day, the hero gets a mysterious bill. From that day on, he gets caught up in the turmoil over the resurrection of the anciently sealed demons hidden behind the eerie card game "New Youkai Den". The hero travels all over Japan to prevent the demon from resurrection. There are four game modes: "story mode", "fighting mode", "battle mode", and "trading mode". In "Battle Mode" and "Trading Mode", you can play and exchange with your friends using a communication cable. There are 298 types of cards by Shigeru Mizuki, the best youkai painter of our time!' FROM games WHERE igdb_id = 282235 ON CONFLICT (game_id, language_code) DO NOTHING;
