INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-powerpuff-girls-battle-him', 49832, '2001-03-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5qbn.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Powerpuff Girls: Battle HIM', 'One of three POWERPUFF GIRLS games released together on the Game Boy Color, THE POWER PUFF GIRLS: Battle Him cats you in the role of the lovable Bubbles. Bubbles'' nurturing personality shines in the video game, as you help her collect power-ups and battle the infamous, evil "Him." She might be an elementary school student, but she''ll prove just how dedicated she is to crime fighting, as you help Bubbles shoot her way through level after level of original action. Many of the items that you collect throughout the adventure can be traded for others via friends playing the other POWERPUFF GIRLS games on their systems. Although it''s a one-player game, the trading aspect gives the experience a significantly interactive element. Of course, the brilliant sense of humor from the cartoon series is present throughout the adventure, as are all of the other characters you''ve come to love. Handheld video games just don''t get much more creative (or fun) than this.' FROM games WHERE igdb_id = 49832 ON CONFLICT (game_id, language_code) DO NOTHING;
