INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Sail II', 'Age of Sail II simulates naval warfare from 1775 to 1820 with a real-time 3-D sailing and combat model. Over 1,200 historical ships and 100 historical American and British scenarios are available, including: Copenhagen, the Battle of the Nile, Trafalgar, Cape St. Vincent, and Camperdown. A full, floating 3-D camera allows complete control of your fleet, and the 3-D accelerated graphics reveal accurately rendered ships and beautiful landscapes' FROM games WHERE igdb_id = 9428 ON CONFLICT (game_id, language_code) DO NOTHING;
