INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Rage 3', 'Race against speed freaks and adrenaline junkies on tough mountain tracks in this fast and Furious championship. Engage in time trails and intense 400-meter races in your quest to win the "Fastest of the Pass" title. Win the Battle King mode and race against the famous Drift King. Drive 30 actual modes from six Japanese famous auto manufacturers (Honda, Mazda, Mitsubishi, Nissan, Subaru, Toyota). The game also includes a two-player mode.' FROM games WHERE igdb_id = 43536 ON CONFLICT (game_id, language_code) DO NOTHING;
