INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fuuraiki', 'Fūraiki is a visual novel blending photographic backgrounds with anime-style character overlays. The player character is a travel blogger and photographer, who travels to Japan''s northernmost island of Hokkaido to document his journeys for his blog. On the boat to the island, he encounters a number of young girls also traveling there, whom you will have additional opportunities to meet during the main part of the game.' FROM games WHERE igdb_id = 64665 ON CONFLICT (game_id, language_code) DO NOTHING;
