INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blaster-master-blasting-again', 45096, '2001-03-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9b58.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blaster Master: Blasting Again', 'Years ago, the Earth was threatened by an evil being known as the Plutonium Boss. The Plutonium Boss and his minions were devouring the Earth from within, and if they had succeeded, Earth would''ve been destroyed. He didn''t count on a young man named Jason, a beautiful alien woman named Eve, and their battle tank, the Sofia MA-01...because of his underestimation, the Plutonium Boss was defeated. Since then, Jason had been defending the Earth from any threat that arises, with Eve by his side. She even bore him two children, Roddy and Elfie. Jason trained Elfie in engineering, and Roddy in battling in Sofia. But now Jason and Eve have died, and Roddy must take his father''s place as defender of the Earth. And an old threat seems to be arising to challenge this new generation of heroes...' FROM games WHERE igdb_id = 45096 ON CONFLICT (game_id, language_code) DO NOTHING;
