INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 71: The Renai Simulation 2', 'Simple 1500 Series Vol. 71: The Renai Simulation 2 is a classic adventure dating simulation game. The player takes the role of a young student (19 years old) called Yahagi Shiyunpei that failed to enter university and start working as an assistant professor in a private school and he got the mission of trying to help 5 girls that study there to pass the exams, and to do that he will have to help them to study during the summer. During the summer he will also got the chance to date them and maybe fall in love with any of them.' FROM games WHERE igdb_id = 203067 ON CONFLICT (game_id, language_code) DO NOTHING;
