INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('desperados-wanted-dead-or-alive', 7260, '2001-04-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22xz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21q7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Desperados: Wanted Dead or Alive', 'Play six Desperados, lead by the hero John Cooper in the hardest and wildest Wild West Game of all times. Guide Cooper and his fearless companions in the exciting pursuit of the mysterious bandit leader El Diabolo. Breath-taking landscapes and a thrilling story create an unmatched Wild West atmosphere resulting in “Desperados – Wanted Dead or Alive” being a challenging team based real-time-adventure-strategy-game. The Wild West has never been this entertaining! 6 different game characters, each of them having special abilities 25 real time-strategy missions full of action Award-winning full motion videos with thrilling plots Unique sceneries including ghost towns, gold mines, pueblos, swamps, camps saloons, prisons and steamers Thrilling gun fights, bank robberies, ambush missions, traps and breakneck pursuits Spectacular effects in the landscapes including thunderstorms, sun sets, caves, fires and waterfalls 6 practice missions to get used to controlling the characters Altogether more than 30 different characteristics to be used by you skillfully in order to survive the levels and to escape' FROM games WHERE igdb_id = 7260 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 7260 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
